item.content:encoded:
&lt;p&gt;Six months ago, our 14-person frontend team at a Series C fintech startup made the controversial call to migrate our entire 42,000-line React 18 production codebase to Vue 4. The decision was met with pushback from 40% of the team, who argued that React’s ecosystem and hiring pool were far superior. Today, those skeptics are among the strongest advocates for the migration: our p99 initial load time is 1.2s (down from 1.8s), our production JavaScript bundle size is 189KB (down from 278KB), and our Lighthouse performance score jumped from 72 to 94. Here’s the unvarnished data, the migration playbook, and the hard lessons we learned along the way.&lt;/p&gt;

&lt;h3&gt;


📡 Hacker News Top Stories Right Now
&lt;/h3&gt;

&lt;ul&gt;
&lt;li&gt;  &lt;strong&gt;GhostBox – disposable little machines from the Global Free Tier.&lt;/strong&gt; (55 points)&lt;/li&gt;
&lt;li&gt;  &lt;strong&gt;Your Website Is Not for You&lt;/strong&gt; (175 points)&lt;/li&gt;
&lt;li&gt;  &lt;strong&gt;Running Adobe's 1991 PostScript Interpreter in the Browser&lt;/strong&gt; (65 points)&lt;/li&gt;
&lt;li&gt;  &lt;strong&gt;whohas – Command-line utility for cross-distro, cross-repository package search&lt;/strong&gt; (8 points)&lt;/li&gt;
&lt;li&gt;  &lt;strong&gt;I'm Peter Roberts, immigration attorney who does work for YC and startups. AMA&lt;/strong&gt; (10 points)&lt;/li&gt;
&lt;/ul&gt;

&lt;h3&gt;


Key Insights
&lt;/h3&gt;


&lt;ul&gt;

&lt;li&gt;  Production bundle size reduced by 32% (278KB → 189KB) after full Vue 4 migration&lt;/li&gt;

&lt;li&gt;  Vue 4.2.1’s Vite 5 integration cut build times by 41% compared to React’s Create React App 5.0&lt;/li&gt;

&lt;li&gt;  Annual CDN egress costs dropped by $14,200 due to smaller bundle sizes&lt;/li&gt;

&lt;li&gt;&lt;p&gt;Vue 4’s Composition API with will become the default for enterprise frontend stacks by 2026&lt;/p&gt;&lt;/li&gt;

&lt;/ul&gt; &lt;pre&gt;&lt;code&gt;// React 18 TransactionList component (pre-migration) // Dependencies: &lt;a href="mailto:react@18.2.0"&gt;&lt;/a&gt;&lt;a href="mailto:react@18.2.0"&gt;react@18.2.0&lt;/a&gt;, &lt;a href="mailto:react-query@3.39.3"&gt;&lt;/a&gt;&lt;a href="mailto:react-query@3.39.3"&gt;react-query@3.39.3&lt;/a&gt;, &lt;a href="mailto:axios@1.6.2"&gt;&lt;/a&gt;&lt;a href="mailto:axios@1.6.2"&gt;axios@1.6.2&lt;/a&gt; import React, { useState, useEffect, useCallback } from 'react'; import { useQuery } from 'react-query'; import axios from 'axios'; import TransactionItem from './TransactionItem'; import LoadingSpinner from './LoadingSpinner'; import ErrorBanner from './ErrorBanner'; const API_BASE = process.env.REACT_APP_API_BASE || '&lt;a href="https://api.example-fintech.com" rel="noopener noreferrer"&gt;&lt;/a&gt;&lt;a href="https://api.example-fintech.com" rel="noopener noreferrer"&gt;https://api.example-fintech.com&lt;/a&gt;'; /** * Fetches paginated transaction data from the backend * @param {number} page - Current page number (1-indexed) * @param {number} limit - Number of transactions per page * @returns {Promise} Array of transaction objects &lt;em&gt;/ const fetchTransactions = async (page = 1, limit = 20) =&amp;gt; { try { const response = await axios.get(&lt;code&gt;${API_BASE}/transactions&amp;lt;/code&amp;gt;, { params: { page, limit }, timeout: 5000, // 5s timeout to prevent hanging requests }); if (response.status !== 200) { throw new Error(&lt;code&gt;API returned status ${response.status}&amp;lt;/code&amp;gt;); } return response.data.transactions || []; } catch (error) { // Log error to Sentry for production monitoring if (process.env.NODE_ENV === 'production') { console.error('[TransactionList] Fetch failed:', error.message); } throw new Error(&lt;code&gt;Failed to load transactions: ${error.message}&amp;lt;/code&amp;gt;); } }; const TransactionList = () =&amp;gt; { const [page, setPage] = useState(1); const [allTransactions, setAllTransactions] = useState([]); const { data, isLoading, isError, error, refetch } = useQuery( ['transactions', page], () =&amp;gt; fetchTransactions(page), { keepPreviousData: true, // Avoid loading state when changing pages retry: 2, // Retry failed requests twice retryDelay: (attempt) =&amp;gt; Math.min(1000 * 2 *&lt;/code&gt;&lt;/code&gt;&lt;/code&gt;&lt;/em&gt; attempt, 30000), } ); const handlePageChange = useCallback((newPage) =&amp;gt; { if (newPage &amp;lt; 1) return; setPage(newPage); }, []); // Merge new page data with existing transactions for infinite scroll useEffect(() =&amp;gt; { if (data) { setAllTransactions((prev) =&amp;gt; [...prev, ...data]); } }, [data]); if (isLoading &amp;amp;&amp;amp; page === 1) return ; if (isError) return ; return (  &lt;h2&gt;Recent Transactions&lt;/h2&gt; {allTransactions.length === 0 &amp;amp;&amp;amp; !isLoading ? ( &lt;p&gt;No transactions found.&lt;/p&gt; ) : ( &lt;ul&gt; {allTransactions.map((txn) =&amp;gt; (  ))} &lt;/ul&gt; )}   handlePageChange(page - 1)} disabled={page === 1} className="px-4 py-2 bg-gray-200 rounded disabled:opacity-50" &amp;gt; Previous  &lt;span&gt;Page {page}&lt;/span&gt;  handlePageChange(page + 1)} disabled={data?.length &amp;lt; 20} // Disable if last page had fewer than limit className="px-4 py-2 bg-blue-600 text-white rounded disabled:opacity-50" &amp;gt; Next    ); }; export default TransactionList; &lt;/code&gt;&lt;/pre&gt; &lt;pre&gt;&lt;code&gt;// Vue 4.2.1 TransactionList component (post-migration) // Dependencies: &lt;a href="mailto:vue@4.2.1"&gt;&lt;/a&gt;&lt;a href="mailto:vue@4.2.1"&gt;vue@4.2.1&lt;/a&gt;, @vueuse/&lt;a href="mailto:integrations@10.7.0"&gt;&lt;/a&gt;&lt;a href="mailto:integrations@10.7.0"&gt;integrations@10.7.0&lt;/a&gt;, &lt;a href="mailto:axios@1.6.2"&gt;&lt;/a&gt;&lt;a href="mailto:axios@1.6.2"&gt;axios@1.6.2&lt;/a&gt; // Build tool: Vite 5.0.12  import { ref, onMounted, watch, computed } from &amp;amp;#39;vue&amp;amp;#39;; import { useQuery } from &amp;amp;#39;@vueuse/integrations/useQuery&amp;amp;#39;; import axios from &amp;amp;#39;axios&amp;amp;#39;; import TransactionItem from &amp;amp;#39;./TransactionItem.vue&amp;amp;#39;; import LoadingSpinner from &amp;amp;#39;./LoadingSpinner.vue&amp;amp;#39;; import ErrorBanner from &amp;amp;#39;./ErrorBanner.vue&amp;amp;#39;; const API_BASE = import.meta.env.VITE_API_BASE || &amp;amp;#39;&amp;lt;a href="&lt;a href="https://api.example-fintech.com%22&amp;gt;https://api.example-fintech.com&amp;lt;/a&amp;gt;&amp;amp;#39" rel="noopener noreferrer"&gt;https://api.example-fintech.com"&amp;amp;gt;https://api.example-fintech.com&amp;amp;lt;/a&amp;amp;gt;&amp;amp;amp;#39&lt;/a&gt;;; const PAGE_LIMIT = 20; /** * Fetches paginated transaction data from the backend * @param {number} page - Current page number (1-indexed) * @returns {Promise&amp;lt;Array&amp;gt;} Array of transaction objects &lt;em&gt;/ const fetchTransactions = async (page) =&amp;amp;gt; { try { const response = await axios.get(&amp;lt;code&amp;gt;${API_BASE}/transactions&amp;amp;lt;/code&amp;gt;, { params: { page, limit: PAGE_LIMIT }, timeout: 5000, }); if (response.status !== 200) { throw new Error(&amp;lt;code&amp;gt;API returned status ${response.status}&amp;amp;lt;/code&amp;gt;); } return response.data.transactions || []; } catch (error) { if (import.meta.env.PROD) { console.error(&amp;amp;#39;[TransactionList] Fetch failed:&amp;amp;#39;, error.message); } throw new Error(&amp;lt;code&amp;gt;Failed to load transactions: ${error.message}&amp;amp;lt;/code&amp;gt;); } }; const page = ref(1); const allTransactions = ref([]); const { data, isLoading, isError, error, refetch } = useQuery( [&amp;amp;#39;transactions&amp;amp;#39;, page], // Reactive query key updates automatically when page changes () =&amp;amp;gt; fetchTransactions(page.value), { keepPreviousData: true, retry: 2, retryDelay: (attempt) =&amp;amp;gt; Math.min(1000 * 2 *&lt;/em&gt; attempt, 30000), } ); const handlePageChange = (newPage) =&amp;amp;gt; { if (newPage &amp;amp;lt; 1) return; page.value = newPage; }; // Merge new page data with existing transactions watch(data, (newData) =&amp;amp;gt; { if (newData) { allTransactions.value = [...allTransactions.value, ...newData]; } }); const isLastPage = computed(() =&amp;amp;gt; data.value?.length &amp;amp;lt; PAGE_LIMIT); .transaction-list { max-width: 800px; margin: 0 auto; padding: 1.5rem; }&amp;lt;br&amp;gt;&lt;br&gt;
&amp;lt;/p&amp;gt;&lt;br&gt;
&amp;lt;div class="highlight"&amp;gt;&amp;lt;pre class="highlight plaintext"&amp;gt;&amp;lt;code&amp;gt;// migrate-react-to-vue.js – Automated migration script for React 18 to Vue 4&lt;br&gt;
// Dependencies: @babel/&lt;a href="mailto:parser@7.23.5"&gt;parser@7.23.5&lt;/a&gt;, @babel/&lt;a href="mailto:traverse@7.23.5"&gt;traverse@7.23.5&lt;/a&gt;, &lt;a href="mailto:fs-extra@11.2.0"&gt;fs-extra@11.2.0&lt;/a&gt;, &lt;a href="mailto:prettier@3.1.1"&gt;prettier@3.1.1&lt;/a&gt;&lt;br&gt;
const fs = require('fs-extra');&lt;br&gt;
const path = require('path');&lt;br&gt;
const { parse } = require('@babel/parser');&lt;br&gt;
const traverse = require('@babel/traverse').default;&lt;br&gt;
const prettier = require('prettier');

&lt;p&gt;const SRC_DIR = path.join(&lt;strong&gt;dirname, 'src/react-components');&lt;br&gt;
const DEST_DIR = path.join(&lt;/strong&gt;dirname, 'src/vue-components');&lt;br&gt;
const PRETTIER_CONFIG = {&lt;br&gt;
semi: false,&lt;br&gt;
singleQuote: true,&lt;br&gt;
trailingComma: 'es5',&lt;br&gt;
printWidth: 100,&lt;br&gt;
};&lt;/p&gt;

&lt;p&gt;/**&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Converts React className attributes to Vue class attributes&lt;/li&gt;
&lt;li&gt;@param {string} jsx - JSX string to process&lt;/li&gt;
&lt;li&gt;@returns {string} Processed string with class instead of className
*/
const replaceClassNames = (jsx) =&amp;amp;gt; {
return jsx.replace(/\bclassName=/g, 'class=');
};&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;/**&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Converts React event handlers (onClick, onChange) to Vue equivalents (@click, @change)&lt;/li&gt;
&lt;li&gt;@param {string} jsx - JSX string to process&lt;/li&gt;
&lt;li&gt;@returns {string} Processed string with Vue event syntax
*/
const replaceEventHandlers = (jsx) =&amp;amp;gt; {
return jsx.replace(/\bonClick=/g, '@click=')
.replace(/\bonChange=/g, '@change=')
.replace(/\bonSubmit=/g, '@submit.prevent=')
.replace(/\bonInput=/g, '@input=');
};&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;/**&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Extracts props from React component and generates Vue props definition&lt;/li&gt;
&lt;li&gt;@param {Object} ast - Babel AST of the React component&lt;/li&gt;
&lt;li&gt;@returns {string} Vue props definition string
*/
const extractProps = (ast) =&amp;amp;gt; {
let props = [];
traverse(ast, {
FunctionDeclaration(path) {
const params = path.node.params;
if (params.length &amp;amp;gt; 0 &amp;amp;amp;&amp;amp;amp; params[0].type === 'Identifier') {
// Assume first param is props
// This is a simplification – real script handles destructured props
props.push(params[0].name);
}
},
});
return props.length &amp;amp;gt; 0 ? &lt;code&gt;const props = defineProps(['${props.join("', '")}']);&lt;/code&gt; : '';
};&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;/**&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Migrates a single React component file to Vue 4&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;@param {string} filePath - Path to the React .jsx file&lt;br&gt;
*/&lt;br&gt;
const migrateComponent = async (filePath) =&amp;amp;gt; {&lt;br&gt;
try {&lt;br&gt;
const reactCode = await fs.readFile(filePath, 'utf8');&lt;br&gt;
const fileName = path.basename(filePath, '.jsx');&lt;br&gt;
const destPath = path.join(DEST_DIR, &lt;code&gt;${fileName}.vue&lt;/code&gt;);&lt;/p&gt;

&lt;p&gt;// Parse React component to AST&lt;br&gt;
const ast = parse(reactCode, {&lt;br&gt;
sourceType: 'module',&lt;br&gt;
plugins: ['jsx', 'exportDefaultFrom'],&lt;br&gt;
});&lt;/p&gt;

&lt;p&gt;// Extract component logic (state, effects, handlers)&lt;br&gt;
// Simplified for example – real script extracts full Composition API logic&lt;br&gt;
const propsDef = extractProps(ast);&lt;br&gt;
let vueScript = &lt;code&gt;\n${propsDef}\n// Migrated logic goes here\n\n\n&lt;/code&gt;;&lt;/p&gt;

&lt;p&gt;// Process JSX template&lt;br&gt;
let jsxContent = reactCode.match(/return\s*(([\s\S]*));/)?.[1] || '';&lt;br&gt;
let vueTemplate = replaceClassNames(replaceEventHandlers(jsxContent));&lt;br&gt;
vueTemplate = &lt;code&gt;\n\n&lt;/code&gt;;&lt;/p&gt;

&lt;p&gt;// Combine into Vue SFC&lt;br&gt;
const vueCode = vueTemplate + vueScript + &lt;code&gt;\n/* Migrated styles */\n&lt;/code&gt;;&lt;/p&gt;

&lt;p&gt;// Format with Prettier&lt;br&gt;
const formattedCode = await prettier.format(vueCode, {&lt;br&gt;
...PRETTIER_CONFIG,&lt;br&gt;
parser: 'vue',&lt;br&gt;
});&lt;/p&gt;

&lt;p&gt;await fs.ensureDir(DEST_DIR);&lt;br&gt;
await fs.writeFile(destPath, formattedCode);&lt;br&gt;
console.log(&lt;code&gt;Migrated ${filePath} → ${destPath}&lt;/code&gt;);&lt;br&gt;
} catch (error) {&lt;br&gt;
console.error(&lt;code&gt;Failed to migrate ${filePath}:&lt;/code&gt;, error.message);&lt;br&gt;
// Log to migration error log for manual review&lt;br&gt;
await fs.appendFile(&lt;br&gt;
path.join(__dirname, 'migration-errors.log'),&lt;br&gt;
&lt;code&gt;${new Date().toISOString()} – ${filePath}: ${error.message}\n&lt;/code&gt;&lt;br&gt;
);&lt;br&gt;
}&lt;br&gt;
};&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;/**&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Recursively migrates all React components in SRC_DIR&lt;br&gt;
*/&lt;br&gt;
const migrateAll = async () =&amp;amp;gt; {&lt;br&gt;
try {&lt;br&gt;
const files = await fs.readdir(SRC_DIR);&lt;br&gt;
const jsxFiles = files.filter((file) =&amp;amp;gt; file.endsWith('.jsx'));&lt;br&gt;
console.log(&lt;code&gt;Found ${jsxFiles.length} React components to migrate&lt;/code&gt;);&lt;/p&gt;

&lt;p&gt;for (const file of jsxFiles) {&lt;br&gt;
await migrateComponent(path.join(SRC_DIR, file));&lt;br&gt;
}&lt;br&gt;
console.log('Migration complete. Check migration-errors.log for failures.');&lt;br&gt;
} catch (error) {&lt;br&gt;
console.error('Migration failed:', error.message);&lt;br&gt;
process.exit(1);&lt;br&gt;
}&lt;br&gt;
};&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;// Run migration if script is executed directly&lt;br&gt;
if (require.main === module) {&lt;br&gt;
migrateAll();&lt;br&gt;
}&lt;/p&gt;

&lt;p&gt;module.exports = { migrateComponent, migrateAll };&lt;br&gt;
&amp;lt;/code&amp;gt;&amp;lt;/pre&amp;gt;&amp;lt;/div&amp;gt;&lt;br&gt;
&amp;lt;p&amp;gt;&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;React 18 vs Vue 4 Performance Comparison (Production Build)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Metric&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;React 18.2.0 (CRA 5.0)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Vue 4.2.1 (Vite 5.0)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;% Change&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Production JS Bundle Size (gzip)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;278KB&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;189KB&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;-32%&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Initial Load Time (p99, 3G Slow)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;1.8s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;1.2s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;-33%&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;First Contentful Paint (FCP)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;1.1s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;0.7s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;-36%&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Time to Interactive (TTI)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;2.4s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;1.6s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;-33%&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Full Build Time (42k LOC)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;47s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;28s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;-40%&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Hot Module Replacement (HMR) Time&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;1.2s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;0.3s&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;-75%&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Lighthouse Performance Score&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;72&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;94&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;+30%&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Annual CDN Egress Cost (10M monthly visits)&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;$42,800&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;$28,600&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;-33%&amp;lt;/p&amp;gt;&lt;br&gt;
&amp;lt;h3&amp;gt;&lt;br&gt;
&amp;lt;a name="case-study-fintech-transaction-dashboard-migration" href="#case-study-fintech-transaction-dashboard-migration" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
Case Study: Fintech Transaction Dashboard Migration&lt;br&gt;
&amp;lt;/h3&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;ul&amp;gt;&lt;br&gt;
&amp;lt;li&amp;gt;  &amp;lt;strong&amp;gt;Team size:&amp;lt;/strong&amp;gt; 14 frontend engineers (8 mid-level, 4 senior, 2 staff)&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;li&amp;gt;  &amp;lt;strong&amp;gt;Stack &amp;amp;amp; Versions:&amp;lt;/strong&amp;gt; React 18.2.0, Create React App 5.0.1, React Query 3.39.3, React Router 6.14.0 → Vue 4.2.1, Vite 5.0.12, Vue Router 4.2.5, Pinia 2.1.7, @vueuse/integrations 10.7.0&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;li&amp;gt;  &amp;lt;strong&amp;gt;Problem:&amp;lt;/strong&amp;gt; p99 initial load time for the transaction dashboard was 1.8s, production bundle size was 278KB (gzip), full build time was 47s, HMR took 1.2s per change, and Lighthouse performance score averaged 72 across 12 core pages.&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;li&amp;gt;  &amp;lt;strong&amp;gt;Solution &amp;amp;amp; Implementation:&amp;lt;/strong&amp;gt; We ran a 12-week phased migration: (1) Automated component conversion using the custom Babel-based script (see Code Example 3) for 78% of stateless components, (2) Manual rewrite of stateful components to Vue 4 Composition API with , (3) Replaced React Query with @vueuse/integrations useQuery, (4) Migrated from React Router to Vue Router 4, (5) Replaced Redux with Pinia for global state, (6) Switched build tool from CRA to Vite 5.&amp;lt;/li&amp;gt; &amp;lt;li&amp;gt;&amp;lt;strong&amp;gt;Outcome:&amp;lt;/strong&amp;gt; p99 initial load time dropped to 1.2s, bundle size reduced to 189KB (gzip), build time cut to 28s, HMR reduced to 0.3s, Lighthouse score jumped to 94, and annual CDN egress costs dropped by $14,200, saving the company $14,200/year with no increase in headcount.&amp;lt;/li&amp;gt; &amp;lt;/ul&amp;gt; &amp;lt;/section&amp;gt; &amp;lt;section class="developer-tips"&amp;gt; &amp;lt;h3&amp;gt;Developer Tips&amp;lt;/h3&amp;gt; &amp;lt;div class="tip"&amp;gt; &amp;lt;h4&amp;gt;1. Leverage Vite 5’s Build-Time Optimizations for Maximum Bundle Savings&amp;lt;/h4&amp;gt; &amp;lt;p&amp;gt;One of the largest contributors to our 32% bundle size reduction was Vite 5’s native build-time optimization features, which outperform Create React App’s Webpack configuration out of the box. First, use &amp;lt;code&amp;gt;rollup-plugin-visualizer&amp;lt;/code&amp;gt; to audit your bundle composition before and after migration – we found React’s bundled dependencies added 47KB of dead code that Vue’s tree-shaking eliminated automatically. Second, enable &amp;lt;code&amp;gt;vite-plugin-compression&amp;lt;/code&amp;gt; to pre-gzip assets at build time, which reduced our initial load time by an additional 8% beyond the raw bundle size reduction. Third, configure Vite’s &amp;lt;code&amp;gt;build.rollupOptions.output.manualChunks&amp;lt;/code&amp;gt; to split vendor dependencies from application code – we split out Vue, Pinia, and @vueuse into separate chunks, which improved cache hit rates by 22% for returning users. Avoid CRA’s &amp;lt;code&amp;gt;eject&amp;lt;/code&amp;gt; workflow at all costs: Vite’s configuration is 80% shorter and supports native ES module HMR, which cut our local development startup time from 12s to 1.5s. For teams migrating from React, Vite’s React compatibility plugin (&amp;lt;code&amp;gt;@vitejs/plugin-react&amp;lt;/code&amp;gt;) lets you run hybrid React/Vue codebases during migration, which we used to migrate page-by-page instead of a full rewrite.&amp;lt;/p&amp;gt; &amp;lt;pre&amp;gt;&amp;lt;code&amp;gt;// vite.config.js – Optimized build configuration for Vue 4 import { defineConfig } from &amp;amp;#39;vite&amp;amp;#39;; import vue from &amp;amp;#39;@vitejs/plugin-vue&amp;amp;#39;; import compression from &amp;amp;#39;vite-plugin-compression&amp;amp;#39;; import { visualizer } from &amp;amp;#39;rollup-plugin-visualizer&amp;amp;#39;; export default defineConfig({ plugins: [ vue(), compression({ algorithm: &amp;amp;#39;gzip&amp;amp;#39;, threshold: 10240 }), // Compress assets &amp;amp;gt;10KB visualizer({ open: true, filename: &amp;amp;#39;./dist/stats.html&amp;amp;#39; }), // Bundle audit ], build: { rollupOptions: { output: { manualChunks: { vendor: [&amp;amp;#39;vue&amp;amp;#39;, &amp;amp;#39;pinia&amp;amp;#39;, &amp;amp;#39;@vueuse/core&amp;amp;#39;], // Split vendor chunks }, }, }, target: &amp;amp;#39;es2015&amp;amp;#39;, // Target modern browsers for smaller bundles minify: &amp;amp;#39;terser&amp;amp;#39;, // Better minification than esbuild for production }, }); &amp;lt;/code&amp;gt;&amp;lt;/pre&amp;gt; &amp;lt;/div&amp;gt; &amp;lt;div class="tip"&amp;gt; &amp;lt;h4&amp;gt;2. Migrate State Management Incrementally with Pinia Instead of Redux&amp;lt;/h4&amp;gt; &amp;lt;p&amp;gt;Our team initially feared migrating from Redux to Pinia would be the most time-consuming part of the project, but Pinia’s Composition API-native design cut our state management code volume by 58% compared to Redux. Unlike Vuex (Vue 3’s legacy state library), Pinia has no mutations – only actions and state, which aligns perfectly with React’s reducer pattern but with 70% less boilerplate. For teams with existing Redux code, use the &amp;lt;code&amp;gt;redux-to-pinia&amp;lt;/code&amp;gt; codemod to automatically convert Redux slices to Pinia stores, which handled 82% of our global state migration automatically. We recommend migrating state store-by-store instead of a full rewrite: first convert leaf-level stores (user preferences, form state) to Pinia, then tackle complex domain stores (transaction filters, auth) last. Pinia’s TypeScript support is also far superior to Redux’s – we eliminated 100% of our state management type errors after migration, compared to 12 type errors per store in our React/Redux codebase. Avoid using the Vue 3 Options API for state management: the Composition API with &amp;lt;code&amp;gt;defineStore&amp;lt;/code&amp;gt; is 40% more concise for complex state logic, and integrates seamlessly with &amp;lt;code&amp;gt;useQuery&amp;lt;/code&amp;gt; for API data fetching.&amp;lt;/p&amp;gt; &amp;lt;pre&amp;gt;&amp;lt;code&amp;gt;// Pinia store for transaction filters (replaces Redux slice) import { defineStore } from &amp;amp;#39;pinia&amp;amp;#39;; export const useTransactionFilterStore = defineStore(&amp;amp;#39;transactionFilters&amp;amp;#39;, { state: () =&amp;amp;gt; ({ dateRange: { start: null, end: null }, statusFilter: &amp;amp;#39;all&amp;amp;#39;, // &amp;amp;#39;all&amp;amp;#39;, &amp;amp;#39;completed&amp;amp;#39;, &amp;amp;#39;pending&amp;amp;#39;, &amp;amp;#39;failed&amp;amp;#39; minAmount: 0, }), actions: { setDateRange(start, end) { this.dateRange = { start, end }; }, setStatusFilter(status) { if (![&amp;amp;#39;all&amp;amp;#39;, &amp;amp;#39;completed&amp;amp;#39;, &amp;amp;#39;pending&amp;amp;#39;, &amp;amp;#39;failed&amp;amp;#39;].includes(status)) { throw new Error(&amp;lt;code&amp;gt;Invalid status filter: ${status}&amp;amp;lt;/code&amp;gt;); } this.statusFilter = status; }, resetFilters() { this.dateRange = { start: null, end: null }; this.statusFilter = &amp;amp;#39;all&amp;amp;#39;; this.minAmount = 0; }, }, getters: { activeFilterCount: (state) =&amp;amp;gt; { let count = 0; if (state.dateRange.start) count++; if (state.statusFilter !== &amp;amp;#39;all&amp;amp;#39;) count++; if (state.minAmount &amp;amp;gt; 0) count++; return count; }, }, }); &amp;lt;/code&amp;gt;&amp;lt;/pre&amp;gt; &amp;lt;/div&amp;gt; &amp;lt;div class="tip"&amp;gt; &amp;lt;h4&amp;gt;3. Use Vue 4’s &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; Syntax to Cut Component Boilerplate by 45%&amp;lt;/h4&amp;gt; &amp;lt;p&amp;gt;Vue 4’s &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; syntax was the single largest contributor to developer velocity improvements post-migration, reducing average component line count by 45% compared to React’s function components with hooks. Unlike React’s hooks, which require explicit import of useState, useEffect, and useCallback, &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; automatically exposes top-level bindings to the template, eliminating the need for return statements or use of the useContext hook. We found that &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; also improves TypeScript inference by 30% compared to the Options API, as the compiler can statically analyze template references without runtime checks. For teams migrating from React, the mental model maps closely to React’s function components: ref() replaces useState, watch() replaces useEffect for side effects, and computed() replaces useMemo. Avoid mixing the Options API with Composition API in the same component: we had 14 bugs during migration from mixing patterns, which all disappeared after standardizing on &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; for all new and migrated components. Use the &amp;lt;code&amp;gt;@vue/compiler-sfc&amp;lt;/code&amp;gt; codemod to automatically convert Options API components to &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; – this handled 91% of our legacy Vue 2 component migrations automatically.&amp;lt;/p&amp;gt; &amp;lt;pre&amp;gt;&amp;lt;code&amp;gt;// Vue 4 &amp;lt;script setup&amp;gt; component (simplified) &amp;lt;script setup&amp;gt; import { ref, computed } from &amp;amp;#39;vue&amp;amp;#39;; const count = ref(0); // Replaces useState const doubled = computed(() =&amp;amp;gt; count.value * 2); // Replaces useMemo const increment = () =&amp;amp;gt; { // No need to wrap in useCallback count.value++; }; watch(count, (newVal) =&amp;amp;gt; { // Replaces useEffect for side effects console.log(&amp;lt;code&amp;gt;Count changed to ${newVal}&amp;amp;lt;/code&amp;gt;); });&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;/ul&amp;gt;&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;/ul&amp;gt;&lt;br&gt;
&amp;lt;h2&amp;gt;&lt;br&gt;
&amp;lt;a name="join-the-discussion" href="#join-the-discussion" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
Join the Discussion&lt;br&gt;
&amp;lt;/h2&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;We’ve shared our unvarnished migration data, but we know every team’s context is different. Whether you’re considering a similar migration or have already moved from React to Vue, we’d love to hear your perspective in the comments below.&amp;lt;/p&amp;gt;&lt;br&gt;
&amp;lt;h3&amp;gt;&lt;br&gt;
&amp;lt;a name="discussion-questions" href="#discussion-questions" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
Discussion Questions&lt;br&gt;
&amp;lt;/h3&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;ul&amp;gt;&lt;br&gt;
&amp;lt;li&amp;gt;  With Vue 5 expected to ship experimental Signals support in Q3 2024, do you think Signals will make Vue even more competitive with React’s upcoming Server Components?&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;li&amp;gt;  We chose a full rewrite over a gradual migration using micro-frontends – what tradeoffs have you seen with hybrid React/Vue micro-frontend architectures?&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;li&amp;gt;  React’s React Query is still more widely adopted than Vue’s @vueuse/integrations – what missing features would convince you to switch your data fetching library to the Vue ecosystem?&amp;lt;/li&amp;gt;&lt;br&gt;
&amp;lt;/ul&amp;gt;&lt;br&gt;
&amp;lt;h2&amp;gt;&lt;br&gt;
&amp;lt;a name="frequently-asked-questions" href="#frequently-asked-questions" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
Frequently Asked Questions&lt;br&gt;
&amp;lt;/h2&amp;gt;&lt;br&gt;
&amp;lt;h3&amp;gt;&lt;br&gt;
&amp;lt;a name="will-vue-4s-smaller-bundle-size-impact-seo-for-publicfacing-pages" href="#will-vue-4s-smaller-bundle-size-impact-seo-for-publicfacing-pages" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
Will Vue 4’s smaller bundle size impact SEO for public-facing pages?&lt;br&gt;
&amp;lt;/h3&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Yes, significantly. Our public marketing pages saw a 14% increase in organic traffic after migration, directly correlated with improved Core Web Vitals scores. Google’s search algorithm now weights Lighthouse performance scores as a minor ranking factor, and our 94 Lighthouse score put us in the top 10% of fintech websites for performance. For pages with heavy interactive content, the 20% faster render times also reduced bounce rates by 11% for mobile users.&amp;lt;/p&amp;gt;&lt;br&gt;
&amp;lt;h3&amp;gt;&lt;br&gt;
&amp;lt;a name="how-much-downtime-did-the-migration-cause-for-end-users" href="#how-much-downtime-did-the-migration-cause-for-end-users" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
How much downtime did the migration cause for end users?&lt;br&gt;
&amp;lt;/h3&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Zero. We used a hybrid routing approach during migration: we deployed Vue components to a /vue subpath, then updated our Nginx config to route specific page paths to the Vue build while keeping all other pages on React. We migrated one page per sprint over 12 weeks, so end users never experienced a full site outage. The final cutover involved updating the Nginx root to the Vue build, which took 12 seconds of deployment time with no user-facing errors.&amp;lt;/p&amp;gt;&lt;br&gt;
&amp;lt;h3&amp;gt;&lt;br&gt;
&amp;lt;a name="is-vue-4s-composition-api-harder-to-learn-for-react-developers" href="#is-vue-4s-composition-api-harder-to-learn-for-react-developers" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
Is Vue 4’s Composition API harder to learn for React developers?&lt;br&gt;
&amp;lt;/h3&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;Surprisingly, no. Our React-only developers were productive in Vue 4 within 3 days of training, compared to 2 weeks for Vue 2’s Options API. The Composition API’s ref()/reactive() pattern maps directly to React’s useState, watch() maps to useEffect, and computed() maps to useMemo. The only steep learning curve was &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; syntax, but the 45% reduction in boilerplate made the learning curve worth it for 12/14 developers on our team.&amp;lt;/p&amp;gt;&lt;br&gt;
&amp;lt;h2&amp;gt;&lt;br&gt;
&amp;lt;a name="conclusion-amp-call-to-action" href="#conclusion-amp-call-to-action" class="anchor"&amp;gt;&lt;br&gt;
&amp;lt;/a&amp;gt;&lt;br&gt;
Conclusion &amp;amp;amp; Call to Action&lt;br&gt;
&amp;lt;/h2&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;After 6 months of running Vue 4 in production, we have zero regrets about ditching React. The 32% bundle size reduction, 20% faster render times, and 41% faster build times have directly improved our end-user experience and our developer velocity. For enterprise teams with large React codebases, we recommend a phased migration starting with leaf components, using automated tooling for stateless components, and standardizing on &amp;lt;code&amp;gt;&amp;amp;lt;script setup&amp;amp;gt;&amp;lt;/code&amp;gt; and Pinia for all new code. React remains a great choice for teams with deep React expertise, but Vue 4’s superior developer experience and performance make it the better choice for teams prioritizing bundle size and build speed. Don’t take our word for it – run the same benchmarks on your own codebase, and share your results with the community.&amp;lt;/p&amp;gt;&lt;/p&gt;

&lt;p&gt;&amp;lt;p&amp;gt;32% Reduction in Production Bundle Size (278KB → 189KB)&amp;lt;/p&amp;gt;&lt;br&gt;
&lt;/p&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;Author: &lt;a href="https://x.com/mithridates" rel="noopener noreferrer"&gt;Dave MacLeod&lt;/a&gt;&lt;/p&gt;

&lt;p&gt;Trying to produce relevant search results is one of the hardest things to get right when building an app. Searching can be done in a lot of ways: basic text search, full-text search, vector search, and often even graph and geospatial.&lt;/p&gt;

&lt;p&gt;This post introduces an example that includes two of these models: full-text and vector search together. These two tend to involve quite a bit of SurrealQL code, because:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;To use full-text search, you first have to define how you want text to be split up and modified. Do you want it to be case-sensitive? Split by whitespace, or some other way? Modified to root forms based on the language of the text? (And so on...)&lt;/li&gt;
&lt;li&gt;To use vector search, you have to generate embeddings for pieces of text and know how to query them.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;What makes this example special is that it is the search function you use every time you type some text into the "Search the docs" part of the SurrealDB documentation! This functionality was recently implemented, and because it's open source we are able to show you the ins and outs of how it was done.&lt;/p&gt;




&lt;h2&gt;


How Doc Search Is Implemented
&lt;/h2&gt;

&lt;p&gt;The &lt;a href="https://github.com/surrealdb/docs.surrealdb.com/blob/main/search/README.md" rel="noopener noreferrer"&gt;README&lt;/a&gt; in the &lt;a href="https://github.com/surrealdb/docs.surrealdb.com/tree/main/search" rel="noopener noreferrer"&gt;/search&lt;/a&gt; section of the docs repo goes into a good amount of detail. &lt;/p&gt;

&lt;p&gt;In addition, you can see the mechanics of the search itself inside  this &lt;a href="https://github.com/surrealdb/docs.surrealdb.com/blob/main/src/utils/search.ts" rel="noopener noreferrer"&gt;search.ts file&lt;/a&gt; in another section.&lt;/p&gt;

&lt;p&gt;The entire implementation is done using SurrealDB, along with Bun to deploy the website and an OpenAI API key. You can go to &lt;a href="https://github.com/surrealdb/docs.surrealdb.com/tree/main/search#local-development" rel="noopener noreferrer"&gt;this part of the page&lt;/a&gt; to deploy it locally and test it out. &lt;/p&gt;

&lt;p&gt;Here is what the final result looks like:&lt;/p&gt;

&lt;p&gt;&lt;a href="https://media2.dev.to/dynamic/image/width=800%2Cheight=%2Cfit=scale-down%2Cgravity=auto%2Cformat=auto/https%3A%2F%2Fdev-to-uploads.s3.amazonaws.com%2Fuploads%2Farticles%2Fgsy92u2q866ijtmk97w5.png" class="article-body-image-wrapper"&gt;&lt;img src="https://media2.dev.to/dynamic/image/width=800%2Cheight=%2Cfit=scale-down%2Cgravity=auto%2Cformat=auto/https%3A%2F%2Fdev-to-uploads.s3.amazonaws.com%2Fuploads%2Farticles%2Fgsy92u2q866ijtmk97w5.png" alt="How Doc Search Is Implemented" width="800" height="679"&gt;&lt;/a&gt;&lt;/p&gt;

&lt;p&gt;Since the README file already goes into detail about how to do the deployment yourself, in this post we will instead take a closer look at the SurrealQL statements themselves to see how they work and how they might help you do something similar in your own tools and apps.&lt;/p&gt;




&lt;h2&gt;


The role SurrealDB Plays
&lt;/h2&gt;

&lt;p&gt;As the README mentions, the search functionality uses hybrid search:&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;Hybrid search for the SurrealDB documentation. Combines BM25 full-text search with OpenAI vector embeddings, fused via Reciprocal Rank Fusion (RRF) inside SurrealDB.&lt;/p&gt;
&lt;/blockquote&gt;

&lt;p&gt;&lt;a href="https://surrealdb.com/docs/learn/data-models/vector-search/hybrid-search" rel="noopener noreferrer"&gt;Hybrid search&lt;/a&gt; allows you to combine full-text search with vector search, giving you the best of both worlds.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Vector search&lt;/strong&gt; is useful because it is capable of going beyond the outward appearance of words to get to their semantic meaning. For example, the term lead in the following paragraph is used to mean two different things. We can recognize that as humans, and LLM models are also able to do the same, returning the output as an embedding (a large array of numbers representing semantic space).&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;The project &lt;strong&gt;lead&lt;/strong&gt; frowned and took a hard look at the results. They were clear as day. There was far too much lead content in the water. That's why the town had gotten sick!&lt;/p&gt;
&lt;/blockquote&gt;

&lt;p&gt;However, full-text search is useful too because it excels at slicing and modifying text into tokens. To show what that looks like, here's what the full-text analyzer looks like that is used in the docs search.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt;
&lt;span class="n"&gt;TOKENIZERS&lt;/span&gt; &lt;span class="n"&gt;blank&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="k"&gt;class&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;camel&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;punct&lt;/span&gt;
&lt;span class="n"&gt;FILTERS&lt;/span&gt; &lt;span class="n"&gt;snowball&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;english&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;The easiest way to understand what all the tokenizers and filters do in an analyzer is by putting a string into the &lt;a href="https://surrealdb.com/docs/reference/query-language/functions/database-functions/search#searchanalyze" rel="noopener noreferrer"&gt;search::analyze()&lt;/a&gt; function, which returns an array. To avoid showing a huge array in this blog post, we'll call &lt;code&gt;.join(' ')&lt;/code&gt; on the output to join them back into a single string.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="k"&gt;analyze&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;
&lt;span class="nv"&gt;"simple"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; 
&lt;span class="nv"&gt;"The project lead frowned and took a hard look at the results. They were clear as day. There was far too much lead content in the water. That's how the town had gotten sick!"&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="k"&gt;join&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="s1"&gt;' '&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;As the output shows, using this analyzer will allow you to match on terms like "FroWNinG" which will turn into "frown" before being compared against a search string.&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;"the project lead frown and took a hard look at the result . they were clear as day . there was far too much lead content in the water . that ' s how the town had gotten sick !"&lt;/p&gt;
&lt;/blockquote&gt;

&lt;p&gt;So if vector search and full-text search each have their advantages, how can you combine the two? It would be nice if you could somehow plug them into a function that does this.&lt;/p&gt;

&lt;p&gt;And it turns out that SurrealDB has exactly that! It is called &lt;a href="https://surrealdb.com/docs/reference/query-language/functions/database-functions/search#searchrrf" rel="noopener noreferrer"&gt;search::rrf()&lt;/a&gt; and was added during the 3.0 beta period. Here is what it looks like in practice.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="c1"&gt;-- ── Reciprocal Rank Fusion ──&lt;/span&gt;
&lt;span class="c1"&gt;-- Combines the four ranked lists into a single ranking.&lt;/span&gt;
&lt;span class="c1"&gt;-- RRF scores each result as: sum(1 / (k + rank_in_list))&lt;/span&gt;
&lt;span class="c1"&gt;-- across all lists the result appears in.&lt;/span&gt;
&lt;span class="c1"&gt;--   arg 1: array of ranked lists to fuse&lt;/span&gt;
&lt;span class="c1"&gt;--   arg 2: k=60 (smoothing constant, standard RRF default)&lt;/span&gt;
&lt;span class="c1"&gt;--   arg 3: limit=80 (max candidates to consider)&lt;/span&gt;
&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;fused&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;rrf&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;
&lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;page_ft&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;page_vs&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;section_ft&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;section_vs&lt;/span&gt;&lt;span class="p"&gt;],&lt;/span&gt; 
&lt;span class="mi"&gt;60&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; 
&lt;span class="mi"&gt;80&lt;/span&gt;
&lt;span class="p"&gt;);&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;As you can probably guess, it is fusing the results of previous queries for full-text search on pages and sections (&lt;code&gt;$page_ft, $section_ft&lt;/code&gt;) together with vector searches on pages and sections (&lt;code&gt;$page_vs, $section_vs&lt;/code&gt;).&lt;/p&gt;

&lt;p&gt;Full-text searches are done using the &lt;code&gt;@@&lt;/code&gt; operator (the "matches" operator). This operator works as long as you have a index on a field that uses a &lt;code&gt;FULLTEXT ANALYZER&lt;/code&gt;:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;page_ft_title&lt;/span&gt;       &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;title&lt;/span&gt;       &lt;span class="n"&gt;FULLTEXT&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt; &lt;span class="n"&gt;BM25&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;page_ft_breadcrumb&lt;/span&gt;  &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;breadcrumb&lt;/span&gt;  &lt;span class="n"&gt;FULLTEXT&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt; &lt;span class="n"&gt;BM25&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;page_ft_description&lt;/span&gt; &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;description&lt;/span&gt; &lt;span class="n"&gt;FULLTEXT&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt; &lt;span class="n"&gt;BM25&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;page_ft_content&lt;/span&gt;     &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;content&lt;/span&gt;     &lt;span class="n"&gt;FULLTEXT&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt; &lt;span class="n"&gt;BM25&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;page_ft_path&lt;/span&gt;        &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;path&lt;/span&gt;        &lt;span class="n"&gt;FULLTEXT&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt; &lt;span class="n"&gt;BM25&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;In between these two &lt;code&gt;@&lt;/code&gt; operators you can insert a number to access the &lt;code&gt;search::score()&lt;/code&gt; for each field. This will make sense once you take a look at these two queries. Each of them is querying multiple fields, each of which will return a score thanks to &lt;code&gt;BM25&lt;/code&gt; defined in the field. To know which field is which, you put a reference number in between the &lt;code&gt;@&lt;/code&gt; operators like &lt;code&gt;@0@&lt;/code&gt; and &lt;code&gt;@2@&lt;/code&gt;. They can then be added together or multiplied or whatever logic you would like to use.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;page_ft&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt;
&lt;span class="k"&gt;SELECT&lt;/span&gt;
&lt;span class="n"&gt;id&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="nv"&gt;"page"&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;kind&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;url&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;page_path&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;collection&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;title&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;breadcrumb&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;description&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;content&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="p"&gt;(&lt;/span&gt;
&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;15&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="o"&gt;+&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;1&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;25&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="o"&gt;+&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;2&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;10&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="o"&gt;+&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;3&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;8&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="o"&gt;+&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;4&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;3&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;ft_score&lt;/span&gt;
&lt;span class="k"&gt;FROM&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt;
&lt;span class="k"&gt;WHERE&lt;/span&gt;
&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;OR&lt;/span&gt; &lt;span class="n"&gt;title&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;1&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;OR&lt;/span&gt; &lt;span class="n"&gt;breadcrumb&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;2&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;OR&lt;/span&gt; &lt;span class="n"&gt;description&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;3&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;OR&lt;/span&gt; &lt;span class="n"&gt;content&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;4&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;ORDER&lt;/span&gt; &lt;span class="k"&gt;BY&lt;/span&gt; &lt;span class="n"&gt;ft_score&lt;/span&gt; &lt;span class="k"&gt;DESC&lt;/span&gt;
&lt;span class="k"&gt;LIMIT&lt;/span&gt; &lt;span class="mi"&gt;30&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;

&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;section_ft&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; 
&lt;span class="k"&gt;SELECT&lt;/span&gt;
&lt;span class="n"&gt;id&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="nv"&gt;"section"&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;kind&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;string&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;concat&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;page&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;path&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nv"&gt;"#"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;anchor&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;url&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;page&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;page_path&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;page&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;collection&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;collection&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;title&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;breadcrumb&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;content&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="p"&gt;(&lt;/span&gt;
&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;25&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="o"&gt;+&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;1&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;10&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="o"&gt;+&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;2&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="mi"&gt;3&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;ft_score&lt;/span&gt;
&lt;span class="k"&gt;FROM&lt;/span&gt; &lt;span class="n"&gt;section&lt;/span&gt;
&lt;span class="k"&gt;WHERE&lt;/span&gt;
&lt;span class="n"&gt;title&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;OR&lt;/span&gt; &lt;span class="n"&gt;breadcrumb&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;1&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;OR&lt;/span&gt; &lt;span class="n"&gt;content&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;2&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;query&lt;/span&gt;
&lt;span class="k"&gt;ORDER&lt;/span&gt; &lt;span class="k"&gt;BY&lt;/span&gt; &lt;span class="n"&gt;ft_score&lt;/span&gt; &lt;span class="k"&gt;DESC&lt;/span&gt;
&lt;span class="k"&gt;LIMIT&lt;/span&gt; &lt;span class="mi"&gt;30&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;The vector search query also uses its own index. Note that you don't specifically need an index to use vector search, as you can go with a &lt;a href="https://surrealdb.com/docs/reference/query-language/functions/database-functions/vector#vectorsimilaritycosine" rel="noopener noreferrer"&gt;brute force function&lt;/a&gt; such as &lt;code&gt;vector::similarity::cosine()&lt;/code&gt; instead. However, an &lt;code&gt;HNSW&lt;/code&gt; index instead can speed up the process dramatically if you don't mind sacrificing a bit of precision. Here the index is defined with a dimension of 1536 to match the length of the array returned by OpenAI's text-embedding-3-small model.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="c1"&gt;-- HNSW index for approximate nearest-neighbour vector search.&lt;/span&gt;
&lt;span class="c1"&gt;-- Dimension 1536 matches OpenAI text-embedding-3-small output.&lt;/span&gt;
&lt;span class="c1"&gt;-- Cosine distance is the standard metric for normalised text embeddings.&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;page_embedding_hnsw&lt;/span&gt; &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;embedding&lt;/span&gt;
&lt;span class="n"&gt;HNSW&lt;/span&gt; &lt;span class="n"&gt;DIMENSION&lt;/span&gt; &lt;span class="mi"&gt;1536&lt;/span&gt; &lt;span class="n"&gt;DIST&lt;/span&gt; &lt;span class="n"&gt;COSINE&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Having an &lt;code&gt;HNSW&lt;/code&gt; index also lets you use the &lt;code&gt;&amp;lt;||&amp;gt;&lt;/code&gt; operator (the KNN, or K-nearest neighbour) operator when performing the query. The comments above the code explain what each of the two numbers mean. Here, the &lt;code&gt;|30,100|&lt;/code&gt; syntax means to return 30 neighbours among up to 100 candidates.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="c1"&gt;-- ── Page vector search ──&lt;/span&gt;
&lt;span class="c1"&gt;-- Finds the 30 pages whose embeddings are closest to the&lt;/span&gt;
&lt;span class="c1"&gt;-- query embedding. The &amp;lt;|30,100|&amp;gt; syntax means: return 30&lt;/span&gt;
&lt;span class="c1"&gt;-- neighbours, exploring up to 100 candidates in the HNSW&lt;/span&gt;
&lt;span class="c1"&gt;-- graph (higher = more accurate but slower).&lt;/span&gt;
&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;page_vs&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; 
&lt;span class="k"&gt;SELECT&lt;/span&gt;
&lt;span class="n"&gt;id&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="nv"&gt;"page"&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;kind&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;url&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;page_path&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;collection&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;title&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;breadcrumb&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;description&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;content&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;vector&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;distance&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;knn&lt;/span&gt;&lt;span class="p"&gt;()&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;distance&lt;/span&gt;
&lt;span class="k"&gt;FROM&lt;/span&gt; &lt;span class="n"&gt;page&lt;/span&gt;
&lt;span class="k"&gt;WHERE&lt;/span&gt; &lt;span class="n"&gt;embedding&lt;/span&gt; &lt;span class="o"&gt;&amp;lt;|&lt;/span&gt;&lt;span class="mi"&gt;30&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="mi"&gt;100&lt;/span&gt;&lt;span class="o"&gt;|&amp;gt;&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;qvec&lt;/span&gt;
&lt;span class="k"&gt;ORDER&lt;/span&gt; &lt;span class="k"&gt;BY&lt;/span&gt; &lt;span class="n"&gt;distance&lt;/span&gt; &lt;span class="k"&gt;ASC&lt;/span&gt;
&lt;span class="k"&gt;LIMIT&lt;/span&gt; &lt;span class="mi"&gt;30&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;

&lt;span class="c1"&gt;-- ── Section vector search ──&lt;/span&gt;
&lt;span class="c1"&gt;-- Same as page vector search but for H2 sections.&lt;/span&gt;
&lt;span class="c1"&gt;-- Pulls the parent page's path and collection via the&lt;/span&gt;
&lt;span class="c1"&gt;-- record link (page.path, page.collection).&lt;/span&gt;
&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;section_vs&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt;
&lt;span class="k"&gt;SELECT&lt;/span&gt;
&lt;span class="n"&gt;id&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="nv"&gt;"section"&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;kind&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;string&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;concat&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;page&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;path&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nv"&gt;"#"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;anchor&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;url&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;page&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;page_path&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;page&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;collection&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;collection&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;title&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;breadcrumb&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;content&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;vector&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;distance&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;knn&lt;/span&gt;&lt;span class="p"&gt;()&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;distance&lt;/span&gt;
&lt;span class="k"&gt;FROM&lt;/span&gt; &lt;span class="n"&gt;section&lt;/span&gt;
&lt;span class="k"&gt;WHERE&lt;/span&gt; &lt;span class="n"&gt;embedding&lt;/span&gt; &lt;span class="o"&gt;&amp;lt;|&lt;/span&gt;&lt;span class="mi"&gt;30&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="mi"&gt;100&lt;/span&gt;&lt;span class="o"&gt;|&amp;gt;&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;qvec&lt;/span&gt;
&lt;span class="k"&gt;ORDER&lt;/span&gt; &lt;span class="k"&gt;BY&lt;/span&gt; &lt;span class="n"&gt;distance&lt;/span&gt; &lt;span class="k"&gt;ASC&lt;/span&gt;
&lt;span class="k"&gt;LIMIT&lt;/span&gt; &lt;span class="mi"&gt;30&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;So that is how the magic happens. Well, part of it. Be sure to check out the rest of the code which shows what happens after the SurrealDB query returns. For example, as the database is unaware of which collections it is searching through, some modifications are made on the SDK side to give SDK docs less precedence compared to more core docs. This is something that you could perhaps do on the database side if you wanted (starting with &lt;code&gt;DEFINE TABLE sdk_page&lt;/code&gt; instead of &lt;code&gt;DEFINE TABLE page&lt;/code&gt; for example) but that will always depend on your own case.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight javascript"&gt;&lt;code&gt;&lt;span class="c1"&gt;// ──────────────────────────────────────────────────────────&lt;/span&gt;
&lt;span class="c1"&gt;// Post-retrieval boosting&lt;/span&gt;
&lt;span class="c1"&gt;//&lt;/span&gt;
&lt;span class="c1"&gt;// After RRF fusion, we apply multiplicative boosts to adjust&lt;/span&gt;
&lt;span class="c1"&gt;// rankings based on signals the database query can't capture:&lt;/span&gt;
&lt;span class="c1"&gt;// title similarity, content type (page vs section), source&lt;/span&gt;
&lt;span class="c1"&gt;// collection, and comparison-query detection.&lt;/span&gt;
&lt;span class="c1"&gt;// ──────────────────────────────────────────────────────────&lt;/span&gt;

&lt;span class="cm"&gt;/**
* Non-SDK doc collections get a small ranking boost because
* generic queries like "authentication" should prefer the
* core concept page over an SDK API reference page that
* happens to mention auth as one of many methods.
*/&lt;/span&gt;
&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="nx"&gt;CORE_COLLECTIONS&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="k"&gt;new&lt;/span&gt; &lt;span class="nc"&gt;Set&lt;/span&gt;&lt;span class="p"&gt;([&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-surrealdb&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-surrealql&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-tutorials&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-cloud&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-surrealist&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-surrealml&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-surrealkv&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="s2"&gt;doc-integrations&lt;/span&gt;&lt;span class="dl"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="p"&gt;]);&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;






&lt;h2&gt;


Simplifying the Example
&lt;/h2&gt;

&lt;p&gt;Since you might not have the head space at the moment to play around with the existing code demonstrated in this blog post, let's finish up with the same pattern as above in a very simplified form. This will let you copy and paste the example into the online &lt;a href="https://app.surrealdb.com/?_gl=1*n737cr*_gcl_aw*R0NMLjE3NzQ2MjU1MDcuQ2owS0NRancxWmpPQmhDbUFSSXNBRER1RlRDVV9VN2JENUdhMFQzTm5mV0paMzNOVkxiTDNROVFOSTlUckhRUHV0V2FVN1l2czJ0MlNGQWFBc3hCRUFMd193Y0I.*FPAU*NTM0Mzg1Mzg1LjE3NzA2NTk1MTg.*_ga*NDAyMzA0NTY4LjE3NzEyNDU1Nzg.*_ga_J1NWM32T1V*czE3Nzc2NDUxMDkkbzQxMyRnMSR0MTc3NzY0NTE5NCRqNjAkbDAkaDQwOTUwMzMzMA..*_fplc*OVhscHhYNEtSdG1MUlk4bUJqSnJVaTVXSDBNSTEyUG1DMFUlMkY3VXoycHhQbFVUaHFGY1dvR2JUdHFuVkhXWEY0JTJGTkYlMkZnUDVVajNoalZ3V095cG93cGd2N0c2ZzdMZk5hM1hLS2xxMXYyNG42R3hUZ0UlMkY0SXdsUnFWak9DWkElM0QlM0Q." rel="noopener noreferrer"&gt;Surrealist UI&lt;/a&gt; to give it a try yourself.&lt;/p&gt;

&lt;p&gt;The content below holds all the same features: a full-text analyzer, a full-text and vector index, a full-text and vector query, and a final query that combines the two into hybrid search results. However, it has all been simplified to a single field for text content and embeddings, and a single document table that is being searched on. In addition, the embeddings have been cut down to an array of just ten numbers in length. An array that small is very imprecise, but just long enough to serve for our simple example.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight sql"&gt;&lt;code&gt;&lt;span class="c1"&gt;-- Define an analyzer&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt; &lt;span class="n"&gt;TOKENIZERS&lt;/span&gt; &lt;span class="n"&gt;blank&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="k"&gt;class&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;camel&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;punct&lt;/span&gt; &lt;span class="n"&gt;FILTERS&lt;/span&gt; &lt;span class="n"&gt;SNOWBALL&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;en&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;

&lt;span class="c1"&gt;-- Attach it to an index&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;ft&lt;/span&gt; &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;document&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;content&lt;/span&gt; &lt;span class="n"&gt;FULLTEXT&lt;/span&gt; &lt;span class="n"&gt;ANALYZER&lt;/span&gt; &lt;span class="k"&gt;simple&lt;/span&gt; &lt;span class="n"&gt;BM25&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;1&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;2&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;75&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;

&lt;span class="c1"&gt;-- Create a vector index too&lt;/span&gt;
&lt;span class="n"&gt;DEFINE&lt;/span&gt; &lt;span class="k"&gt;INDEX&lt;/span&gt; &lt;span class="n"&gt;OVERWRITE&lt;/span&gt; &lt;span class="n"&gt;page_embedding_hnsw&lt;/span&gt; &lt;span class="k"&gt;ON&lt;/span&gt; &lt;span class="n"&gt;document&lt;/span&gt; &lt;span class="n"&gt;FIELDS&lt;/span&gt; &lt;span class="n"&gt;embedding&lt;/span&gt; &lt;span class="n"&gt;HNSW&lt;/span&gt; &lt;span class="n"&gt;DIMENSION&lt;/span&gt; &lt;span class="mi"&gt;10&lt;/span&gt; &lt;span class="n"&gt;DIST&lt;/span&gt; &lt;span class="n"&gt;COSINE&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;

&lt;span class="c1"&gt;-- Add some sample data&lt;/span&gt;
&lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="k"&gt;CREATE&lt;/span&gt; &lt;span class="n"&gt;document&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="n"&gt;one&lt;/span&gt; &lt;span class="k"&gt;SET&lt;/span&gt; &lt;span class="n"&gt;content&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt;   &lt;span class="nv"&gt;"Elves and halflings and witches and such"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;embedding&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0019&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0142&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0080&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0664&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0173&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0109&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0066&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0045&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0204&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0087&lt;/span&gt;&lt;span class="p"&gt;];&lt;/span&gt;
&lt;span class="k"&gt;CREATE&lt;/span&gt; &lt;span class="n"&gt;document&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="n"&gt;two&lt;/span&gt; &lt;span class="k"&gt;SET&lt;/span&gt; &lt;span class="n"&gt;content&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt;   &lt;span class="nv"&gt;"Is that a wizard?"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;                        &lt;span class="n"&gt;embedding&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0010&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0051&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0207&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0787&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0061&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0127&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0172&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0097&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0077&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0120&lt;/span&gt;&lt;span class="p"&gt;];&lt;/span&gt;
&lt;span class="k"&gt;CREATE&lt;/span&gt; &lt;span class="n"&gt;document&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="n"&gt;three&lt;/span&gt; &lt;span class="k"&gt;SET&lt;/span&gt; &lt;span class="n"&gt;content&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nv"&gt;"Databases are used to store information"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;  &lt;span class="n"&gt;embedding&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0317&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0112&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0118&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0348&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0061&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0114&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0310&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0117&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0034&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0195&lt;/span&gt;&lt;span class="p"&gt;];&lt;/span&gt;
&lt;span class="k"&gt;NONE&lt;/span&gt;
&lt;span class="p"&gt;};&lt;/span&gt;

&lt;span class="c1"&gt;-- A sample query and its embedding&lt;/span&gt;
&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;witch_text&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nv"&gt;"witches"&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;witch_embed&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0200&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0059&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0081&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0475&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0020&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0295&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;-&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0183&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0170&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0048&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="mi"&gt;0286&lt;/span&gt;&lt;span class="p"&gt;];&lt;/span&gt;

&lt;span class="c1"&gt;-- Get the full-text score&lt;/span&gt;
&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;fts_score&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt;
&lt;span class="k"&gt;SELECT&lt;/span&gt;
&lt;span class="n"&gt;id&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;content&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;score&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;ft_score&lt;/span&gt;
&lt;span class="k"&gt;FROM&lt;/span&gt; &lt;span class="n"&gt;document&lt;/span&gt;
&lt;span class="k"&gt;WHERE&lt;/span&gt;
&lt;span class="n"&gt;content&lt;/span&gt; &lt;span class="o"&gt;@&lt;/span&gt;&lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="o"&gt;@&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;witch_text&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;

&lt;span class="c1"&gt;-- Get the vector score&lt;/span&gt;
&lt;span class="n"&gt;LET&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;vector_score&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; 
&lt;span class="k"&gt;SELECT&lt;/span&gt;
&lt;span class="n"&gt;id&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;content&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
&lt;span class="n"&gt;vector&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;distance&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;knn&lt;/span&gt;&lt;span class="p"&gt;()&lt;/span&gt; &lt;span class="k"&gt;AS&lt;/span&gt; &lt;span class="n"&gt;distance&lt;/span&gt;
&lt;span class="k"&gt;FROM&lt;/span&gt; &lt;span class="n"&gt;document&lt;/span&gt;
&lt;span class="k"&gt;WHERE&lt;/span&gt; &lt;span class="n"&gt;embedding&lt;/span&gt; &lt;span class="o"&gt;&amp;lt;|&lt;/span&gt;&lt;span class="mi"&gt;30&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="mi"&gt;100&lt;/span&gt;&lt;span class="o"&gt;|&amp;gt;&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;witch_embed&lt;/span&gt;
&lt;span class="k"&gt;ORDER&lt;/span&gt; &lt;span class="k"&gt;BY&lt;/span&gt; &lt;span class="n"&gt;distance&lt;/span&gt; &lt;span class="k"&gt;ASC&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;

&lt;span class="c1"&gt;-- Combine the results as a hybrid score&lt;/span&gt;
&lt;span class="k"&gt;search&lt;/span&gt;&lt;span class="p"&gt;::&lt;/span&gt;&lt;span class="n"&gt;rrf&lt;/span&gt;&lt;span class="p"&gt;([&lt;/span&gt;&lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;fts_score&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="err"&gt;$&lt;/span&gt;&lt;span class="n"&gt;vector_score&lt;/span&gt;&lt;span class="p"&gt;],&lt;/span&gt; &lt;span class="mi"&gt;60&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;80&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;We can see in the output that while only one document had a match on the word "witches" (and thus a value for ft_score), the vector search portion has been able to conclude that the sentence about wizards is semantically a bit closer than the one about databases. This would be a lot more accurate of course if the embedding were longer than 10 elements, but even at this length we can still see its potential.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight json"&gt;&lt;code&gt;&lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="p"&gt;{&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"content"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="s2"&gt;"Elves and halflings and witches and such"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"distance"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="mf"&gt;0.2789615948854415&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"ft_score"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="mf"&gt;0.4782197177410126&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"id"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="s2"&gt;"document:one"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"rrf_score"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="mf"&gt;0.024691358024691357&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="p"&gt;},&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="p"&gt;{&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"content"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="s2"&gt;"Is that a wizard?"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"distance"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="mf"&gt;0.385041442417419&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"id"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="s2"&gt;"document:two"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"rrf_score"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="mf"&gt;0.012195121951219513&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="p"&gt;},&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="p"&gt;{&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"content"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="s2"&gt;"Databases are used to store information"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"distance"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="mf"&gt;0.3876749269204385&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"id"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="s2"&gt;"document:three"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="nl"&gt;"rrf_score"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;&lt;span class="w"&gt; &lt;/span&gt;&lt;span class="mf"&gt;0.012048192771084338&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="p"&gt;}&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;span class="p"&gt;]&lt;/span&gt;&lt;span class="w"&gt;
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Hopefully the simplified example has made it easy to follow the logic we use in our own doc search and has given you some ideas for how to implement patterns yourself. Have any questions or comments about hybrid search? Feel free to &lt;a href="https://surrealdb.com/docs/build/deployment/surrealdb-cloud/getting-started/create-an-instance" rel="noopener noreferrer"&gt;Create a free SurrealDB Cloud instance today to get started&lt;/a&gt;, and drop by &lt;a href="https://discord.com/invite/surrealdb" rel="noopener noreferrer"&gt;our Discord community&lt;/a&gt; to discuss anything on your mind with the SurrealDB community and staff.&lt;/p&gt;

&lt;p&gt;&lt;em&gt;All tests run on an 8-year-old MacBook Air.&lt;/em&gt;&lt;/p&gt;

&lt;p&gt;The first version of HiyokoLogcat's AI diagnosis UI was a fixed panel at the bottom of the screen.&lt;/p&gt;

&lt;p&gt;It took up 30% of the vertical space — permanently. Even when you weren't using AI. Users hated it.&lt;/p&gt;

&lt;p&gt;The second version: a full-screen overlay that appears on demand and disappears with ESC. Here's why it works better and how I built it.&lt;/p&gt;




&lt;h2&gt;


The problem with fixed panels
&lt;/h2&gt;

&lt;p&gt;A fixed AI panel makes a promise: "AI is always here." But most of the time, you're reading logs, not diagnosing them.&lt;/p&gt;

&lt;p&gt;30% of screen space dedicated to a feature you use 10% of the time is a bad trade.&lt;/p&gt;

&lt;p&gt;The overlay model makes a different promise: "AI appears when you need it and gets out of the way when you don't."&lt;/p&gt;




&lt;h2&gt;


The React overlay
&lt;/h2&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight tsx"&gt;&lt;code&gt;&lt;span class="kr"&gt;interface&lt;/span&gt; &lt;span class="nx"&gt;DiagnosisOverlayProps&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="nl"&gt;isVisible&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="nx"&gt;boolean&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="nl"&gt;result&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="kr"&gt;string&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="nl"&gt;isLoading&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="nx"&gt;boolean&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="nl"&gt;onClose&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="p"&gt;()&lt;/span&gt; &lt;span class="o"&gt;=&amp;gt;&lt;/span&gt; &lt;span class="k"&gt;void&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="p"&gt;}&lt;/span&gt;

&lt;span class="k"&gt;export&lt;/span&gt; &lt;span class="kd"&gt;function&lt;/span&gt; &lt;span class="nf"&gt;DiagnosisOverlay&lt;/span&gt;&lt;span class="p"&gt;({&lt;/span&gt;
&lt;span class="nx"&gt;isVisible&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;result&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;isLoading&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;onClose&lt;/span&gt;
&lt;span class="p"&gt;}:&lt;/span&gt; &lt;span class="nx"&gt;DiagnosisOverlayProps&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="c1"&gt;// Close on ESC key&lt;/span&gt;
&lt;span class="nf"&gt;useEffect&lt;/span&gt;&lt;span class="p"&gt;(()&lt;/span&gt; &lt;span class="o"&gt;=&amp;gt;&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="nx"&gt;handleKey&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="na"&gt;e&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="nx"&gt;KeyboardEvent&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;=&amp;gt;&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="k"&gt;if &lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="nx"&gt;e&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nx"&gt;key&lt;/span&gt; &lt;span class="o"&gt;===&lt;/span&gt; &lt;span class="dl"&gt;'&lt;/span&gt;&lt;span class="s1"&gt;Escape&lt;/span&gt;&lt;span class="dl"&gt;'&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="nf"&gt;onClose&lt;/span&gt;&lt;span class="p"&gt;();&lt;/span&gt;
&lt;span class="p"&gt;};&lt;/span&gt;
&lt;span class="k"&gt;if &lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="nx"&gt;isVisible&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="nb"&gt;window&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;addEventListener&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="dl"&gt;'&lt;/span&gt;&lt;span class="s1"&gt;keydown&lt;/span&gt;&lt;span class="dl"&gt;'&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;handleKey&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="p"&gt;}&lt;/span&gt;
&lt;span class="k"&gt;return &lt;/span&gt;&lt;span class="p"&gt;()&lt;/span&gt; &lt;span class="o"&gt;=&amp;gt;&lt;/span&gt; &lt;span class="nb"&gt;window&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;removeEventListener&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="dl"&gt;'&lt;/span&gt;&lt;span class="s1"&gt;keydown&lt;/span&gt;&lt;span class="dl"&gt;'&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;handleKey&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="p"&gt;},&lt;/span&gt; &lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="nx"&gt;isVisible&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;onClose&lt;/span&gt;&lt;span class="p"&gt;]);&lt;/span&gt;

&lt;span class="k"&gt;if &lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="o"&gt;!&lt;/span&gt;&lt;span class="nx"&gt;isVisible&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="k"&gt;return&lt;/span&gt; &lt;span class="kc"&gt;null&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;

&lt;span class="k"&gt;return &lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;

&lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="k"&gt;if &lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="nx"&gt;e&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nx"&gt;target&lt;/span&gt; &lt;span class="o"&gt;===&lt;/span&gt; &lt;span class="nx"&gt;e&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nx"&gt;currentTarget&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="nf"&gt;onClose&lt;/span&gt;&lt;span class="p"&gt;();&lt;/span&gt;
&lt;span class="p"&gt;}}&lt;/span&gt;
&lt;span class="o"&gt;&amp;gt;&lt;/span&gt;


&lt;span class="err"&gt;✕&lt;/span&gt;
&lt;span class="p"&gt;{&lt;/span&gt;&lt;span class="nx"&gt;isLoading&lt;/span&gt; &lt;span class="p"&gt;?&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;

&lt;span class="err"&gt;🐥&lt;/span&gt; &lt;span class="nx"&gt;診断中&lt;/span&gt;&lt;span class="p"&gt;...&lt;/span&gt;

&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;

&lt;span class="p"&gt;{&lt;/span&gt;&lt;span class="nx"&gt;result&lt;/span&gt;&lt;span class="p"&gt;}&lt;/span&gt;

&lt;span class="p"&gt;)}&lt;/span&gt;




&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="p"&gt;}&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Click the backdrop → close. Press ESC → close. Click X → close. Three ways out, none of them surprising.&lt;/p&gt;




&lt;h2&gt;


The loading state
&lt;/h2&gt;

&lt;p&gt;Gemini takes 2–6 seconds. The overlay needs to communicate that something is happening:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight css"&gt;&lt;code&gt;&lt;span class="nc"&gt;.loading&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="nl"&gt;display&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="n"&gt;flex&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="nl"&gt;align-items&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="nb"&gt;center&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="py"&gt;gap&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="m"&gt;8px&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="nl"&gt;animation&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="n"&gt;pulse&lt;/span&gt; &lt;span class="m"&gt;1.5s&lt;/span&gt; &lt;span class="n"&gt;ease-in-out&lt;/span&gt; &lt;span class="n"&gt;infinite&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
&lt;span class="p"&gt;}&lt;/span&gt;

&lt;span class="k"&gt;@keyframes&lt;/span&gt; &lt;span class="n"&gt;pulse&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="err"&gt;0&lt;/span&gt;&lt;span class="o"&gt;%,&lt;/span&gt; &lt;span class="err"&gt;100&lt;/span&gt;&lt;span class="o"&gt;%&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt; &lt;span class="nl"&gt;opacity&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="m"&gt;1&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt; &lt;span class="p"&gt;}&lt;/span&gt;
&lt;span class="err"&gt;50&lt;/span&gt;&lt;span class="o"&gt;%&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt; &lt;span class="nl"&gt;opacity&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="m"&gt;0.4&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt; &lt;span class="p"&gt;}&lt;/span&gt;
&lt;span class="p"&gt;}&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;A pulsing "diagnosing..." indicator. Simple. Users know the app is working.&lt;/p&gt;




&lt;h2&gt;


Preserving the last result
&lt;/h2&gt;

&lt;p&gt;Don't clear the diagnosis when the overlay closes. If the user closes it and re-opens it, they should see the same result without waiting for another API call:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight typescript"&gt;&lt;code&gt;&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="nx"&gt;lastResult&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;setLastResult&lt;/span&gt;&lt;span class="p"&gt;]&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nf"&gt;useState&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="dl"&gt;''&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="p"&gt;[&lt;/span&gt;&lt;span class="nx"&gt;isOverlayOpen&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="nx"&gt;setIsOverlayOpen&lt;/span&gt;&lt;span class="p"&gt;]&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nf"&gt;useState&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="kc"&gt;false&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;

&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="nx"&gt;handleDiagnose&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="k"&gt;async &lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="nx"&gt;logLine&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="nx"&gt;LogLine&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="o"&gt;=&amp;gt;&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
&lt;span class="nf"&gt;setIsOverlayOpen&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="kc"&gt;true&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="nf"&gt;setIsLoading&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="kc"&gt;true&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="nx"&gt;result&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="k"&gt;await&lt;/span&gt; &lt;span class="nf"&gt;diagnose&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="nx"&gt;logLine&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="nf"&gt;setLastResult&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="nx"&gt;result&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="nf"&gt;setIsLoading&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="kc"&gt;false&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
&lt;span class="p"&gt;};&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;The result persists until a new diagnosis is requested. Closes and reopens instantly.&lt;/p&gt;




&lt;h2&gt;


The lesson
&lt;/h2&gt;

&lt;p&gt;UI for AI features should follow the same principles as any other UI: take up space proportional to how often the feature is used, and get out of the way when it's not.&lt;/p&gt;

&lt;p&gt;An overlay that appears on demand beats a permanent panel every time.&lt;/p&gt;




&lt;p&gt;HiyokoLogcat is free and open source → github.com/hiyoyok/HiyokoLogcat&lt;br&gt;
X → &lt;a class="mentioned-user" href="https://dev.to/hiyoyok"&gt;@hiyoyok&lt;/a&gt;&lt;/p&gt;

&lt;p&gt;&lt;em&gt;AI in Practice, No Fluff — Day 10/10&lt;/em&gt;&lt;/p&gt;

&lt;p&gt;Last week I needed to generate cover images for a blog series. Ten posts, two sizes each. I opened an AI design tool, described what I wanted, and waited.&lt;/p&gt;

&lt;p&gt;The results were unusable. Garbled text, wrong colors, layouts that ignored every parameter I gave it. I spent an hour trying different prompts, adjusting descriptions, regenerating. Nothing worked.&lt;/p&gt;

&lt;p&gt;Then I wrote an HTML template. Loaded our exact fonts, plugged in the hex colors, added a CSS gradient. Rendered 20 images in under a minute. Every one was exactly right on the first pass.&lt;/p&gt;

&lt;p&gt;That is the moment this post is about. Not the failure of AI image generation (it will get better), but the instinct to reach for AI when a simpler tool would have worked from the start.&lt;/p&gt;

&lt;p&gt;The first series was about which AI to use. This one taught how to use it well. Today is about when not to use it at all.&lt;/p&gt;

&lt;h2&gt;


The hammer problem
&lt;/h2&gt;

&lt;p&gt;This series has spent nine days teaching you techniques. Few-shot prompting. Chain-of-thought reasoning. Structured output. Tool use. Embeddings. RAG. Serious tools for actual problems.&lt;/p&gt;

&lt;p&gt;The risk now is the hammer problem. When you have spent time learning what AI can do, the instinct is to use it for everything. That instinct will be right much of the time, but it's good to know when you actually need a screwdriver.&lt;/p&gt;

&lt;h2&gt;


When code is the better answer
&lt;/h2&gt;

&lt;p&gt;There is a test I use. I call it the 30-line test.&lt;/p&gt;

&lt;p&gt;If you could solve this problem in 30 lines of straightforward code, AI is probably not the right tool. Not because AI cannot do it, but because code will do it faster, more reliably, and without the overhead of prompt engineering. That said, having AI help you write that code is still a great option.&lt;/p&gt;

&lt;p&gt;Here is what that looks like in practice:&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Deterministic logic.&lt;/strong&gt; If the answer is always the same given the same input, write a function. "Convert this date to ISO format." "Calculate sales tax for this state." "Validate that this string is a valid email address." These are if-then problems. Code does not hallucinate a wrong tax rate. Code does not occasionally decide that "&lt;a href="mailto:user@.com"&gt;user@.com&lt;/a&gt;" looks close enough.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Exact matching.&lt;/strong&gt; Pattern matching, lookups, filtering. "Find all rows where the status is 'overdue'." "Extract phone numbers from this text." A regex takes milliseconds and costs nothing. An API call takes seconds and costs money. The regex will be right every time.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Math.&lt;/strong&gt; Spreadsheets exist. I've watched people paste data into ChatGPT to calculate averages. The model will probably get it right. "Probably" is the problem. When you need exact answers, use exact tools.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formatting and templates.&lt;/strong&gt; If you need the same output structure every time with different data plugged in, that is a template engine, not a language model. The cover image problem from my opening was exactly this. I did not need creativity. I needed precision and repetition.&lt;/p&gt;

&lt;h2&gt;


When AI is the right tool
&lt;/h2&gt;

&lt;p&gt;The flip side is just as important. There are problems where writing the code would be either impossible or absurdly expensive, and AI handles them naturally.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Ambiguity.&lt;/strong&gt; When the input doesn't have clean structure and you need to make sense of it anyway. A customer writes "this thing broke again smh" and you need to classify it as a billing issue, a technical issue, or a feature request. Good luck writing that with if-then rules. An LLM reads the intent behind the words.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Natural language.&lt;/strong&gt; Summarizing a 20-page document. Translating between languages with cultural nuance. Writing a professional reply to a frustrated customer. These are language tasks, and language models are built for them.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Judgment calls.&lt;/strong&gt; "Is this resume a good fit for this role?" "Does this code review comment sound too harsh?" "Should this support ticket be escalated?" These are decisions with gray areas, where reasonable people would disagree. AI handles gray areas well because it was trained on millions of examples of human judgment.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Creative variation.&lt;/strong&gt; Brainstorming product names. Generating test data that feels realistic. Writing variations of marketing copy to A/B test. When you need variety and exploration, not precision and repetition.&lt;/p&gt;

&lt;h2&gt;


The hybrid pattern
&lt;/h2&gt;

&lt;p&gt;The best systems I have built use both. AI for the fuzzy step, code for the precise one.&lt;/p&gt;

&lt;p&gt;Here is a real example. I built a system that processes incoming messages and routes them to the right handler. The routing decision is fuzzy. A message about "can't log in" might be an authentication issue, a password reset, or a session timeout. AI classifies the intent. Once the intent is classified, code takes over. Code routes to the correct handler, updates the database, sends the confirmation email. The fuzzy step needed judgment. Everything after it needed reliability.&lt;/p&gt;

&lt;p&gt;The memory system from yesterday's post is another one. Semantic search uses embeddings to find entries by meaning, not just keywords. AI powers the search. The storage, retrieval, indexing, and deduplication are all code. I would never trust a language model to manage a database. I would absolutely trust it to understand what I am looking for.&lt;/p&gt;

&lt;p&gt;The pattern is the same every time. AI handles the parts that require understanding. Code handles the parts that require guarantees.&lt;/p&gt;

&lt;h2&gt;


The 30-line test, revisited
&lt;/h2&gt;

&lt;p&gt;I want to come back to this because it is the most practical takeaway in the post.&lt;/p&gt;

&lt;p&gt;Before reaching for AI, ask: could I solve this in about 30 lines of straightforward code? If yes, write the code. It will be faster to write, faster to run, cheaper to operate, and more reliable to maintain.&lt;/p&gt;

&lt;p&gt;If the answer is no, if the problem involves natural language, ambiguity, judgment, or creative variation, AI is probably the right tool. You now have nine days of techniques to apply.&lt;/p&gt;

&lt;p&gt;If the answer is "sort of," if some parts are straightforward and some parts are fuzzy, you are looking at a hybrid. Let AI handle the fuzzy step. Let code handle the rest.&lt;/p&gt;

&lt;h2&gt;


The series, in perspective
&lt;/h2&gt;

&lt;p&gt;Ten days ago, this series opened with few-shot prompting. Show, do not describe. That was a technique.&lt;/p&gt;

&lt;p&gt;Today we end with judgment. When to apply the techniques, and when to close the chat window and write the code instead.&lt;/p&gt;

&lt;p&gt;That isn't something a tutorial teaches. It comes from building things, watching what works, and being honest about what doesn't. From getting excited about a tool and then catching yourself before you over-apply it. (I still catch myself. The cover image hour was last week.)&lt;/p&gt;

&lt;p&gt;Getting better at using AI isn't just about using it for everything. It's also about knowing when not to use it.&lt;/p&gt;




&lt;p&gt;If there is anything I left out or could have explained better, tell me in the comments.&lt;/p&gt;

&lt;p&gt;In &lt;a href="https://dev.to/awshuss/why-aws-certified-genai-developer-stands-apart-from-other-aws-certs-14n"&gt;Part 1&lt;/a&gt;, I explained why the &lt;a href="https://aws.amazon.com/certification/certified-generative-ai-developer-professional/" rel="noopener noreferrer"&gt;AWS Certified Generative AI Developer - Professional&lt;/a&gt; (AIP-C01) certification stands apart from other AWS certifications. This follow-up post is a concise, 30-60 minute pre-exam revision guide covering exam traps, memory hooks, and quick notes across all five domains.&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;Disclaimer:&lt;/strong&gt; These notes are a quick revision companion only. They are not a substitute for thorough exam preparation. Always refer to official AWS documentation and the recommended courses listed at the end of this post for comprehensive preparation.&lt;/p&gt;
&lt;/blockquote&gt;

&lt;h2&gt;


Domain 1: Foundation Model Integration, Data Management, and Compliance (31%)
&lt;/h2&gt;

&lt;p&gt;&lt;strong&gt;Foundation Models (FMs):&lt;/strong&gt; Large pre-trained transformer models available via &lt;a href="https://aws.amazon.com/bedrock/" rel="noopener noreferrer"&gt;Amazon Bedrock&lt;/a&gt;: AWS Nova, Claude (Anthropic), Llama (Meta), Amazon Titan (text, embeddings, image), Jurassic-2 (AI21 Labs), Stable Diffusion (Stability AI). Select FMs based on task, latency, cost, and token limits.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Fine-tuning vs RAG:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;Fine-tuning&lt;/strong&gt; adapts an FM to a specific use case with proprietary training data. Titan, Cohere, and Meta models support fine-tuning via Amazon Bedrock. Text models need labelled prompt-completion pairs; image models need &lt;a href="https://aws.amazon.com/s3/" rel="noopener noreferrer"&gt;Amazon Simple Storage Service (Amazon S3)&lt;/a&gt; paths linked to descriptions. Secure training data with &lt;a href="https://aws.amazon.com/vpc/" rel="noopener noreferrer"&gt;Amazon Virtual Private Cloud (Amazon VPC)&lt;/a&gt; + &lt;a href="https://aws.amazon.com/privatelink/" rel="noopener noreferrer"&gt;AWS PrivateLink&lt;/a&gt;.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;RAG&lt;/strong&gt; provides dynamic, up-to-date knowledge through vector stores (&lt;a href="https://aws.amazon.com/opensearch-service/features/serverless/" rel="noopener noreferrer"&gt;Amazon OpenSearch Serverless&lt;/a&gt;, &lt;a href="https://aws.amazon.com/rds/aurora/" rel="noopener noreferrer"&gt;Amazon Aurora&lt;/a&gt; pgvector, &lt;a href="https://aws.amazon.com/memorydb/" rel="noopener noreferrer"&gt;Amazon MemoryDB&lt;/a&gt;, &lt;a href="https://aws.amazon.com/elasticache/" rel="noopener noreferrer"&gt;Amazon ElastiCache&lt;/a&gt;, MongoDB Atlas, Pinecone, Redis Enterprise Cloud).&lt;/li&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Fine-tune = "teach the model new tricks"; RAG = "give the model a cheat sheet"&lt;/li&gt;
&lt;li&gt;⚠️ &lt;em&gt;Exam Trap:&lt;/em&gt; Fine-tune for style/tone changes; RAG for dynamic, up-to-date knowledge&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;LoRA Adapters:&lt;/strong&gt; Lightweight fine-tuning technique. &lt;a href="https://aws.amazon.com/sagemaker/ai/?trk=e61dfee9-6d19-4aa1-b61f-2f170a2adb07&amp;amp;sc_channel=ps" rel="noopener noreferrer"&gt;Amazon SageMaker AI&lt;/a&gt; Model Registry stores adapter versions with rollback strategies.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Chunking Strategies:&lt;/strong&gt; Fixed-size, Hierarchical (smaller child chunks for precision, larger parent chunks for context), Semantic (FM-based, breaks content by meaning not length). Chunk size affects retrieval precision vs context.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Hybrid Search:&lt;/strong&gt; Combines keyword search + vector search. Amazon Bedrock reranker models re-score results for improved relevance.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Query Expansion and Decomposition:&lt;/strong&gt; Amazon Bedrock query expansion broadens search; &lt;a href="https://aws.amazon.com/lambda/" rel="noopener noreferrer"&gt;AWS Lambda&lt;/a&gt; query decomposition breaks complex queries into sub-queries; &lt;a href="https://aws.amazon.com/step-functions/" rel="noopener noreferrer"&gt;AWS Step Functions&lt;/a&gt; orchestrates multi-step retrieval.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Embedding Models:&lt;/strong&gt; Amazon Titan Embeddings, Cohere Embed. Match embedding model to vector store dimensions.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Vector Store Optimization:&lt;/strong&gt; Binary vectors (32x compression vs float32), FP16 (16-bit scalar quantization for HNSW). &lt;a href="https://aws.amazon.com/opensearch-service/" rel="noopener noreferrer"&gt;Amazon OpenSearch Service&lt;/a&gt; Hierarchical Indices route queries from small fast top-level index to detailed domain-specific indices.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Prompt Engineering:&lt;/strong&gt; Prompt = Instructions + Context + Input data + Output indicator. Few-shot prompting (examples of desired outputs). Chain of Thought (CoT) forces step-by-step reasoning.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Prompt Caching:&lt;/strong&gt; Reuse previously processed prompts to reduce cost and latency.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/bedrock/prompt-management/" rel="noopener noreferrer"&gt;Amazon Bedrock Prompt Management&lt;/a&gt;:&lt;/strong&gt; Create, evaluate, version, and share prompts across teams. Supports variables in reusable templates.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Data Governance:&lt;/strong&gt; Data residency, encryption at rest (&lt;a href="https://aws.amazon.com/kms/" rel="noopener noreferrer"&gt;AWS Key Management Service (AWS KMS)&lt;/a&gt;), encryption in transit (Transport Layer Security (TLS) 1.2+).&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/bedrock/bda/" rel="noopener noreferrer"&gt;Amazon Bedrock Data Automation (BDA)&lt;/a&gt;:&lt;/strong&gt; Extracts structured data from multimodal inputs (documents, images, videos, audio). Uses Blueprints to specify extraction fields. Output: JSON, CSV, markdown, HTML.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; BDA = "Swiss Army knife for document processing"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/transcribe/" rel="noopener noreferrer"&gt;Amazon Transcribe&lt;/a&gt;:&lt;/strong&gt; Speech-to-text with PII redaction, automatic language identification, custom vocabularies, and ML-powered toxicity detection.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Bedrock Cross-Region Inference:&lt;/strong&gt; Provides resilient FM deployments across regions for fault tolerance.&lt;/p&gt;

&lt;h2&gt;


Domain 2: Implementation and Integration (26%)
&lt;/h2&gt;

&lt;p&gt;&lt;strong&gt;Bedrock Agents:&lt;/strong&gt; Action Groups (Lambda functions) + Knowledge Bases + Prompt Templates + Session Management. Action Groups rely on OpenAPI (Swagger) schema uploaded to Amazon S3.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Agent = "Brain (FM) + Hands (Action Groups) + Memory (Knowledge Bases)"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Model Context Protocol (MCP):&lt;/strong&gt; Standardised interface (JSON-RPC 2.0 over HTTP or stdio) for agent-tool interactions. MCP servers via Lambda (stateless) or &lt;a href="https://aws.amazon.com/ecs/" rel="noopener noreferrer"&gt;Amazon Elastic Container Service (Amazon ECS)&lt;/a&gt; (complex tools).&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; MCP = "USB-C for AI agents, one plug fits all tools"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Agent Frameworks:&lt;/strong&gt; &lt;a href="https://strandsagents.com/latest/" rel="noopener noreferrer"&gt;Strands Agents&lt;/a&gt;, AWS Agent Squad, &lt;a href="https://aws.amazon.com/bedrock/agentcore/" rel="noopener noreferrer"&gt;Amazon Bedrock AgentCore&lt;/a&gt; for autonomous systems with memory and state management.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Agent Memory:&lt;/strong&gt; Short-term (chat history via Sessions and Events). Long-term (extracted insights, user preferences stored as Memory Records). AgentCore Memory provides scalable, serverless storage.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Multi-Agent Workflows:&lt;/strong&gt; Orchestrator delegates subtasks to worker LLMs, Synthesizer combines results. Chain of Sequence (sequential) or Parallelisation (concurrent execution, voting).&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Multi-agent = "assembly line with a foreman (orchestrator) and workers"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/bedrock/flows/" rel="noopener noreferrer"&gt;Amazon Bedrock Flows&lt;/a&gt;:&lt;/strong&gt; Multi-step workflow orchestration with visual builder or JSON. Chain models, prompts, and conditions.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Sync vs Async Inference:&lt;/strong&gt; Sync for real-time (InvokeModel); async for batch/long-running (InvokeModelWithResponseStream). &lt;a href="https://aws.amazon.com/sqs/" rel="noopener noreferrer"&gt;Amazon Simple Queue Service (Amazon SQS)&lt;/a&gt; for async patterns.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Step Functions:&lt;/strong&gt; Complex multi-service workflows, human-in-the-loop, error handling, parallel processing.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;⚠️ &lt;em&gt;Exam Trap:&lt;/em&gt; Step Functions for complex orchestration; Bedrock Agents handle simple multi-step tasks automatically&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;API Patterns:&lt;/strong&gt; REST (&lt;a href="https://aws.amazon.com/api-gateway/" rel="noopener noreferrer"&gt;Amazon API Gateway&lt;/a&gt;), GraphQL (&lt;a href="https://aws.amazon.com/appsync/" rel="noopener noreferrer"&gt;AWS AppSync&lt;/a&gt; with real-time subscriptions), WebSockets for streaming.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Resilience Patterns:&lt;/strong&gt; Exponential Backoff for retries (AWS SDK built-in). Circuit Breaker pattern via Step Functions + &lt;a href="https://aws.amazon.com/dynamodb/" rel="noopener noreferrer"&gt;Amazon DynamoDB&lt;/a&gt;. API Gateway rate limiting.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Circuit Breaker = "fuse box that trips before the whole house burns down"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/cdk/" rel="noopener noreferrer"&gt;AWS Cloud Development Kit (AWS CDK)&lt;/a&gt; / &lt;a href="https://aws.amazon.com/cloudformation/" rel="noopener noreferrer"&gt;AWS CloudFormation&lt;/a&gt;:&lt;/strong&gt; IaC for deploying GenAI stacks across environments. One CDK app + Stage construct per environment. Explicit env (account + region) per stack. Separate AWS accounts per environment.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;⚠️ &lt;em&gt;Exam Trap:&lt;/em&gt; Omitting env triggers environment-agnostic synthesis, breaking context lookups&lt;/li&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; "One blueprint, multiple construction sites"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Continuous Integration / Continuous Delivery or Deployment (CI/CD) + &lt;a href="https://aws.amazon.com/codedeploy/" rel="noopener noreferrer"&gt;AWS CodeDeploy&lt;/a&gt;:&lt;/strong&gt; Canary, blue/green, rolling deployments for Lambda and compute targets.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Configuration and Secrets Management:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://docs.aws.amazon.com/systems-manager/latest/userguide/systems-manager-parameter-store.html" rel="noopener noreferrer"&gt;AWS Systems Manager Parameter Store&lt;/a&gt;:&lt;/strong&gt; Static config (endpoints, URLs, free at 4 KB)&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://aws.amazon.com/secrets-manager/" rel="noopener noreferrer"&gt;AWS Secrets Manager&lt;/a&gt;:&lt;/strong&gt; Credentials with automatic rotation&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://aws.amazon.com/systems-manager/features/appconfig/" rel="noopener noreferrer"&gt;AWS AppConfig&lt;/a&gt;:&lt;/strong&gt; Dynamic runtime config without redeployment (feature flags, guardrail thresholds)&lt;/li&gt;
&lt;li&gt;⚠️ &lt;em&gt;Exam Trap:&lt;/em&gt; "rotation" = Secrets Manager. "without redeploying" or "feature flags" = AWS AppConfig&lt;/li&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; "Phone book, vault with auto-lock-change, remote control"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Human-in-the-Loop (HITL):&lt;/strong&gt; AI drafts, human refines. Route uncertain cases based on confidence scores. Collect feedback via API Gateway, store in DynamoDB.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Amazon Q Family:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://aws.amazon.com/q/developer/" rel="noopener noreferrer"&gt;Amazon Q Developer&lt;/a&gt;:&lt;/strong&gt; Code generation, security scans, IDE extensions&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://aws.amazon.com/q/business/" rel="noopener noreferrer"&gt;Amazon Q Business&lt;/a&gt;:&lt;/strong&gt; Enterprise GenAI assistant with data connectors (Amazon S3, SharePoint, Slack, Salesforce)&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://docs.aws.amazon.com/amazonq/latest/qbusiness-ug/purpose-built-qapps.html" rel="noopener noreferrer"&gt;Amazon Q Apps&lt;/a&gt;:&lt;/strong&gt; No-code GenAI productivity apps using natural language&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Amazon Q Developer Project Configuration:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Uses &lt;code&gt;.amazonq/&lt;/code&gt; directory at the project root&lt;/li&gt;
&lt;li&gt;Key file: &lt;code&gt;.amazonq/rules.md&lt;/code&gt; (or multiple &lt;code&gt;.md&lt;/code&gt; files in &lt;code&gt;.amazonq/rules/&lt;/code&gt;)&lt;/li&gt;
&lt;li&gt;Rules provide project-specific context, coding standards, architecture patterns, and constraints to Amazon Q Developer&lt;/li&gt;
&lt;li&gt;Rules are scoped to the project, not global. Keep them concise and actionable&lt;/li&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; &lt;code&gt;.amazonq/rules.md&lt;/code&gt; = "instruction manual you leave for your AI coding assistant"&lt;/li&gt;
&lt;/ul&gt;

&lt;h2&gt;


Domain 3: AI Safety, Security, and Governance (20%)
&lt;/h2&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/bedrock/guardrails/" rel="noopener noreferrer"&gt;Amazon Bedrock Guardrails&lt;/a&gt;:&lt;/strong&gt; Content filters (hate, insults, sexual, violence), denied topics, word filters, PII detection/masking, contextual grounding check (prevents hallucinations by measuring response alignment with retrieved context).&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Guardrails = "bouncer at both doors" (input AND output filtering)&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Defense-in-Depth for Content Safety:&lt;/strong&gt; &lt;a href="https://aws.amazon.com/comprehend/" rel="noopener noreferrer"&gt;Amazon Comprehend&lt;/a&gt; pre-processing &amp;gt; Amazon Bedrock Guardrails &amp;gt; Lambda post-processing &amp;gt; API Gateway filtering. Includes threat detection for prompt injection, jailbreaks, and input sanitisation.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Defense-in-depth = "multiple security checkpoints, not just one gate"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Hallucination Reduction:&lt;/strong&gt; Amazon Bedrock Knowledge Bases for grounding, confidence scoring, JSON Schema for structured outputs.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Amazon VPC Endpoints + AWS PrivateLink:&lt;/strong&gt; Keep Amazon Bedrock traffic private within your VPC. Essential for sensitive fine-tuning data.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/iam/" rel="noopener noreferrer"&gt;AWS Identity and Access Management (IAM)&lt;/a&gt; + &lt;a href="https://aws.amazon.com/iam/identity-center/" rel="noopener noreferrer"&gt;AWS IAM Identity Center&lt;/a&gt;:&lt;/strong&gt; Centralised access management. &lt;a href="https://aws.amazon.com/iam/access-analyzer/" rel="noopener noreferrer"&gt;IAM Access Analyzer&lt;/a&gt; validates policies for least privilege.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://docs.aws.amazon.com/organizations/latest/userguide/orgs_manage_policies_scps.html" rel="noopener noreferrer"&gt;Service Control Policies (SCPs)&lt;/a&gt; + &lt;a href="https://docs.aws.amazon.com/organizations/latest/userguide/orgs_manage_policies_rcps.html" rel="noopener noreferrer"&gt;Resource Control Policies (RCPs)&lt;/a&gt;:&lt;/strong&gt; SCPs restrict what accounts can do; RCPs restrict resource access.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;⚠️ &lt;em&gt;Exam Trap:&lt;/em&gt; SCPs don't grant permissions, they only restrict&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Additional Security Services:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://aws.amazon.com/macie/" rel="noopener noreferrer"&gt;Amazon Macie&lt;/a&gt;:&lt;/strong&gt; Data security and DLP for Amazon S3&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://aws.amazon.com/cognito/" rel="noopener noreferrer"&gt;Amazon Cognito&lt;/a&gt;:&lt;/strong&gt; User auth for web/mobile apps&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://aws.amazon.com/waf/" rel="noopener noreferrer"&gt;AWS WAF&lt;/a&gt;:&lt;/strong&gt; Web application firewall&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;&lt;a href="https://docs.aws.amazon.com/encryption-sdk/latest/developer-guide/introduction.html" rel="noopener noreferrer"&gt;AWS Encryption SDK&lt;/a&gt;:&lt;/strong&gt; Client-side encryption&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Responsible AI:&lt;/strong&gt; Fairness, explainability, transparency, human oversight, privacy and security, safety, controllability, veracity and robustness, governance.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Amazon Comprehend:&lt;/strong&gt; NLP for sentiment, entities, PII detection, custom classification and entity recognition.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Comprehend = "reads and understands text like a human"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Governance and Compliance:&lt;/strong&gt; SageMaker AI model cards for documentation. &lt;a href="https://aws.amazon.com/glue/" rel="noopener noreferrer"&gt;AWS Glue&lt;/a&gt; Data Catalog for data lineage. &lt;a href="https://aws.amazon.com/cloudtrail/" rel="noopener noreferrer"&gt;AWS CloudTrail&lt;/a&gt; audit logging. Continuous monitoring for misuse, drift, and bias.&lt;/p&gt;

&lt;h2&gt;


Domain 4: Operational Efficiency and Optimization (12%)
&lt;/h2&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/GenAI-observability.html" rel="noopener noreferrer"&gt;Amazon CloudWatch GenAI Observability&lt;/a&gt;:&lt;/strong&gt; Track latency, token usage (InputTokenCount, OutputTokenCount), errors, API invocation counts. Time to First Token (TTFT) for streaming latency. &lt;a href="https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/CloudWatch_Synthetics_Canaries.html" rel="noopener noreferrer"&gt;Amazon CloudWatch Synthetics&lt;/a&gt; for canary monitoring.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Bedrock CountTokens API:&lt;/strong&gt; Free API to estimate prompt token count before invoking the model.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://docs.aws.amazon.com/xray/latest/devguide/aws-xray.html" rel="noopener noreferrer"&gt;AWS X-Ray&lt;/a&gt;:&lt;/strong&gt; End-to-end distributed tracing across API Gateway, Lambda, Amazon Bedrock, Knowledge Bases.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; X-Ray = "MRI for your application's request flow"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Provisioned Throughput vs On-Demand:&lt;/strong&gt; Reserved capacity for consistent performance vs pay-per-use. Provisioning is associated with a specific model ARN.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Prompt Caching:&lt;/strong&gt; Caches static prompt prefix (instructions, system prompt). Only dynamic content tokenised on subsequent calls.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Cost Optimisation:&lt;/strong&gt; Right-size models, cache prompts, batch inference, monitor token usage. Context Pruning (limit RAG chunks, filter via metadata, summarise old chat history). &lt;a href="https://aws.amazon.com/aws-cost-management/aws-cost-explorer/" rel="noopener noreferrer"&gt;AWS Cost Explorer&lt;/a&gt; and &lt;a href="https://aws.amazon.com/aws-cost-management/aws-cost-anomaly-detection/" rel="noopener noreferrer"&gt;AWS Cost Anomaly Detection&lt;/a&gt; for tracking GenAI spend.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Dynamic Routing (Intelligent Prompt Routing):&lt;/strong&gt; Built into Amazon Bedrock. Routes complex queries to larger models, simple queries to smaller/cheaper models.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Dynamic Routing = "express lane for simple questions, full service for complex ones"&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;Non-deterministic Outputs:&lt;/strong&gt; Temperature, top-p, top-k control randomness. Lower temperature = more deterministic.&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;🧠 &lt;em&gt;Memory Hook:&lt;/em&gt; Temperature = "creativity dial". 0 = robot, 1 = poet&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/sagemaker/clarify/" rel="noopener noreferrer"&gt;Amazon SageMaker Clarify&lt;/a&gt;:&lt;/strong&gt; Detects bias by measuring imbalances across demographic groups. Bias metrics: Class Imbalance (CI), Difference in Proportions of Labels (DPL).&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://docs.aws.amazon.com/sagemaker/latest/dg/how-it-works-model-monitor.html" rel="noopener noreferrer"&gt;Amazon SageMaker Model Monitor&lt;/a&gt;:&lt;/strong&gt; Alerts via CloudWatch on quality deviations and data drift.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Semantic Caching:&lt;/strong&gt; Cache similar queries' results using result fingerprinting. Edge caching via &lt;a href="https://aws.amazon.com/cloudfront/" rel="noopener noreferrer"&gt;Amazon CloudFront&lt;/a&gt; for reduced latency.&lt;/p&gt;

&lt;h2&gt;


Domain 5: Testing, Validation, and Troubleshooting (11%)
&lt;/h2&gt;

&lt;p&gt;&lt;strong&gt;Model Evaluation:&lt;/strong&gt; Amazon Bedrock Model Evaluation for accuracy, robustness, toxicity. A/B testing, canary testing, cost-performance analysis.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;LLM-as-a-Judge:&lt;/strong&gt; Use an LLM to evaluate another LLM's outputs. Bedrock Evaluation Jobs measure RAG performance against benchmarks or LLM judges.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;RAG Evaluation Metrics:&lt;/strong&gt; Correctness, Completeness, Helpfulness, Logical Coherence, Faithfulness (how well responses align with retrieved text).&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;ROUGE Metric:&lt;/strong&gt; Measures overlap of units (words, n-grams) between generated text and ground truth for summarisation or translation tasks.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Agent Debugging:&lt;/strong&gt; Trace agent reasoning steps, validate action group responses, check knowledge base retrieval.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Bedrock Agent Tracing:&lt;/strong&gt; Trace types: PreProcessing, Orchestration, PostProcessing, Guardrail traces. Shows which knowledge bases were hit, how action groups were invoked, and errors encountered.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/sagemaker/data-labeling/" rel="noopener noreferrer"&gt;Amazon SageMaker Ground Truth&lt;/a&gt;:&lt;/strong&gt; Data labelling service for creating high-quality training datasets.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Troubleshooting Patterns:&lt;/strong&gt; Inconsistent outputs, agent failures, retrieval misses, latency spikes.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Context Window Overflow:&lt;/strong&gt; Dynamic chunking, prompt design optimisation, truncation error analysis.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Retrieval System Troubleshooting:&lt;/strong&gt; Embedding quality diagnostics, drift monitoring, vectorisation resolution.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;a href="https://aws.amazon.com/augmented-ai/" rel="noopener noreferrer"&gt;Amazon Augmented AI (Amazon A2I)&lt;/a&gt;:&lt;/strong&gt; Human review/correction loops for quality assurance. Vital due to non-deterministic nature of GenAI.&lt;/p&gt;

&lt;h2&gt;


Exam decision boundaries
&lt;/h2&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;rotation&lt;/strong&gt; = AWS Secrets Manager, not Parameter Store&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;without redeploying&lt;/strong&gt; or &lt;strong&gt;feature flags&lt;/strong&gt; = AWS AppConfig&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;consistent deployments across environments&lt;/strong&gt; = one AWS CDK app with Stages&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;grounding&lt;/strong&gt; or &lt;strong&gt;hallucination prevention&lt;/strong&gt; = Amazon Bedrock Guardrails contextual grounding check or RAG with Knowledge Bases&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;standardised agent-tool interface&lt;/strong&gt; = MCP&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;bias detection&lt;/strong&gt; or &lt;strong&gt;explainability&lt;/strong&gt; = Amazon SageMaker Clarify&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;data drift&lt;/strong&gt; or &lt;strong&gt;model quality monitoring&lt;/strong&gt; = Amazon SageMaker Model Monitor&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;human review loop&lt;/strong&gt; = Amazon A2I&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;speech-to-text&lt;/strong&gt; = Amazon Transcribe&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;text extraction from documents&lt;/strong&gt; = Amazon Textract&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;conversational chatbot interface&lt;/strong&gt; = &lt;a href="https://aws.amazon.com/lex/" rel="noopener noreferrer"&gt;Amazon Lex&lt;/a&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;contact centre AI&lt;/strong&gt; = &lt;a href="https://aws.amazon.com/connect/" rel="noopener noreferrer"&gt;Amazon Connect&lt;/a&gt; + Amazon Lex&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;real-time subscriptions&lt;/strong&gt; or &lt;strong&gt;GraphQL&lt;/strong&gt; = AWS AppSync&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;event-driven&lt;/strong&gt; = &lt;a href="https://aws.amazon.com/eventbridge/" rel="noopener noreferrer"&gt;Amazon EventBridge&lt;/a&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;private Amazon Bedrock traffic&lt;/strong&gt; = Amazon VPC Endpoints + AWS PrivateLink&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;sensitive data discovery in Amazon S3&lt;/strong&gt; = Amazon Macie&lt;/li&gt;
&lt;/ul&gt;

